def _ensure_runtime_dependency(module_name: str, package_spec: str) -> None:
    """Install an optional runtime dependency when a single-file host lacks it."""
    if importlib.util.find_spec(module_name) is not None:
        return
    if os.getenv("AUTO_INSTALL_DEPENDENCIES", "1").strip().lower() in {
        "0", "false", "no", "off",
    }:
        raise RuntimeError(
            f"Missing dependency {package_spec}. Install it before starting the bot."
        )
    subprocess.run(
        [sys.executable, "-m", "pip", "install", "--disable-pip-version-check", package_spec],
        check=True,
        timeout=300,
    )


