def premiumize_text(text: str) -> str:
    """Convert ordinary emoji in bot-authored HTML text to Premium entities."""
    if not PREMIUM_MESSAGE_EMOJIS_ENABLED or not text or "<tg-emoji" in text:
        return text
    result = text
    for fallback in sorted(MESSAGE_PREMIUM_EMOJI_IDS, key=len, reverse=True):
        emoji_id = MESSAGE_PREMIUM_EMOJI_IDS[fallback]
        result = result.replace(
            fallback,
            f'<tg-emoji emoji-id="{emoji_id}">{fallback}</tg-emoji>',
        )
    return result


class PremiumEmojiExtBot(ExtBot):
    """ExtBot that Premium-emoji-renders all bot-authored text and captions."""

    _TEXT_ENDPOINT_FIELDS = {
        "sendMessage": "text",
        "editMessageText": "text",
        "sendPhoto": "caption",
        "sendDocument": "caption",
        "sendAnimation": "caption",
        "sendVideo": "caption",
        "editMessageCaption": "caption",
    }

    async def _post(
        self,
        endpoint: str,
        data: Optional[Dict[str, Any]] = None,
        **kwargs: Any,
    ) -> Any:
        payload = dict(data or {})
        field = self._TEXT_ENDPOINT_FIELDS.get(endpoint)
        if field and isinstance(payload.get(field), str):
            payload[field] = premiumize_text(payload[field])
            payload["parse_mode"] = ParseMode.HTML
        return await super()._post(endpoint, payload, **kwargs)


