CARD_BG = (7, 3, 18)
CARD_PANEL = (18, 10, 37)
CARD_BOX = (29, 15, 55)
CARD_PURPLE = (174, 83, 255)
CARD_PURPLE_SOFT = (116, 64, 185)
CARD_TEXT = (245, 241, 255)
CARD_MUTED = (172, 158, 204)
CARD_GREEN = (107, 235, 166)
CARD_RED = (255, 91, 137)
CARD_GOLD = (245, 196, 74)


@lru_cache(maxsize=2)
def _embedded_card_font_path(bold: bool) -> str:
    font_dir = Path(tempfile.gettempdir()) / "casino_royals_embedded_fonts"
    font_dir.mkdir(parents=True, exist_ok=True)
    path = font_dir / ("DejaVuSans-Bold.ttf" if bold else "DejaVuSans.ttf")
    if not path.exists() or path.stat().st_size < 500000:
        encoded = (
            _EMBEDDED_DEJAVU_BOLD_ZLIB_B64
            if bold else _EMBEDDED_DEJAVU_REGULAR_ZLIB_B64
        )
        raw = zlib.decompress(base64.b64decode(encoded))
        temporary = path.with_suffix(".tmp")
        temporary.write_bytes(raw)
        os.replace(temporary, path)
    return str(path)


@lru_cache(maxsize=64)
def _card_font(size: int, bold: bool = False) -> Any:
    env_key = "CASINO_FONT_BOLD" if bold else "CASINO_FONT_REGULAR"
    candidates = [
        os.getenv(env_key, ""),
        _embedded_card_font_path(bold),
        "/usr/share/fonts/truetype/noto/NotoSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/noto/NotoSans-Regular.ttf",
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        "/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf",
        "C:/Windows/Fonts/arialbd.ttf" if bold else "C:/Windows/Fonts/arial.ttf",
    ]
    for candidate in candidates:
        if candidate and os.path.isfile(candidate):
            return ImageFont.truetype(candidate, size=size)
    return ImageFont.load_default()


def _text_width(draw: Any, text: str, font: Any) -> int:
    box = draw.textbbox((0, 0), str(text), font=font)
    return int(box[2] - box[0])


def _fit_card_text(draw: Any, text: str, font: Any, max_width: int) -> str:
    value = str(text).replace("\n", " ").strip()
    if _text_width(draw, value, font) <= max_width:
        return value
    while value and _text_width(draw, value + "...", font) > max_width:
        value = value[:-1]
    return value.rstrip() + "..."


def _card_money(value: Union[int, float, Decimal]) -> str:
    amount = quantize_money(value)
    return f"₹{int(amount):,}" if amount == amount.to_integral_value() else f"₹{amount:,.2f}"


def _new_card_canvas() -> Tuple[Any, Any]:
    width = height = 1080
    image = Image.new("RGB", (width, height), CARD_BG)
    draw = ImageDraw.Draw(image)
    for y in range(height):
        ratio = y / (height - 1)
        color = (
            int(10 - 3 * ratio),
            int(5 - 2 * ratio),
            int(28 - 10 * ratio),
        )
        draw.line((0, y, width, y), fill=color)
    return image, draw


def _avatar_circle(avatar_bytes: Optional[bytes], size: int, initials: str) -> Any:
    source = None
    if avatar_bytes:
        try:
            source = ImageOps.exif_transpose(Image.open(io.BytesIO(avatar_bytes))).convert("RGB")
            source = ImageOps.fit(source, (size, size), method=Image.Resampling.LANCZOS)
        except Exception:
            source = None
    if source is None:
        source = Image.new("RGB", (size, size), (54, 27, 91))
        draw = ImageDraw.Draw(source)
        label = (initials or "CR")[:2].upper()
        font = _card_font(max(30, size // 3), True)
        box = draw.textbbox((0, 0), label, font=font)
        draw.text(
            ((size - (box[2] - box[0])) / 2, (size - (box[3] - box[1])) / 2 - box[1]),
            label,
            font=font,
            fill=CARD_TEXT,
        )
    mask = Image.new("L", (size, size), 0)
    ImageDraw.Draw(mask).ellipse((0, 0, size - 1, size - 1), fill=255)
    output = Image.new("RGBA", (size, size), (0, 0, 0, 0))
    output.paste(source.convert("RGBA"), (0, 0), mask)
    return output


def _metric_box(
    draw: Any,
    bounds: Tuple[int, int, int, int],
    label: str,
    value: str,
    accent: Tuple[int, int, int],
) -> None:
    x1, y1, x2, y2 = bounds
    draw.rounded_rectangle(bounds, radius=22, fill=CARD_BOX, outline=CARD_PURPLE_SOFT, width=2)
    draw.rounded_rectangle((x1, y1 + 18, x1 + 7, y2 - 18), radius=4, fill=accent)
    draw.text((x1 + 25, y1 + 22), label.upper(), font=_card_font(25), fill=CARD_MUTED)
    font = _card_font(55, True)
    draw.text(
        (x1 + 25, y1 + 58),
        _fit_card_text(draw, value, font, x2 - x1 - 50),
        font=font,
        fill=accent,
    )


def render_stats_card_png(
    stats: Mapping[str, Any],
    avatar_bytes: Optional[bytes],
    usdt_rate: Decimal,
) -> bytes:
    image, draw = _new_card_canvas()
    draw.rounded_rectangle((40, 40, 1040, 1040), radius=34, fill=CARD_PANEL, outline=CARD_PURPLE, width=2)
    username = str(stats.get("username") or "")
    first_name = str(stats.get("first_name") or username or f"Player {stats['user_id']}")
    initials = "".join(part[:1] for part in first_name.split()[:2]) or "CR"
    avatar = _avatar_circle(avatar_bytes, 140, initials)
    image.paste(avatar, (80, 78), avatar)
    name_font = _card_font(54, True)
    draw.text((250, 88), _fit_card_text(draw, first_name, name_font, 500), font=name_font, fill=CARD_TEXT)
    handle = f"@{username}" if username else f"ID {stats['user_id']}"
    draw.text((250, 158), _fit_card_text(draw, handle, _card_font(29), 500), font=_card_font(29), fill=(190, 126, 255))
    balance = quantize_money(stats.get("balance", 0))
    wallet_line = f"Wallet: {fmt_amount(balance)} Coins  |  {fmt_amount(usdt_from_coins(balance, usdt_rate))} USDT"
    draw.text((250, 199), _fit_card_text(draw, wallet_line, _card_font(21), 520), font=_card_font(21), fill=CARD_MUTED)
    rank_text = f"RANK  #{int(stats.get('rank', 0))}"
    draw.rounded_rectangle((790, 88, 998, 154), radius=32, fill=(36, 18, 63), outline=CARD_PURPLE, width=2)
    draw.ellipse((810, 111, 826, 127), fill=CARD_PURPLE)
    draw.text((842, 103), rank_text, font=_card_font(26), fill=(204, 147, 255))
    draw.line((80, 242, 1000, 242), fill=CARD_PURPLE_SOFT, width=2)

    wager = quantize_money(stats.get("total_wager", 0))
    tier = player_tier(wager)
    draw.text((80, 274), "TIER", font=_card_font(24), fill=CARD_MUTED)
    draw.text((80, 310), tier["name"], font=_card_font(42, True), fill=CARD_PURPLE)
    draw.rounded_rectangle((80, 372, 1000, 400), radius=14, fill=(42, 23, 76))
    progress_width = int(920 * float(tier["progress"]))
    if progress_width:
        draw.rounded_rectangle((80, 372, 80 + progress_width, 400), radius=14, fill=CARD_PURPLE)
    draw.text((80, 416), f"{tier['progress'] * 100:.1f}% PROGRESS", font=_card_font(22), fill=CARD_MUTED)
    next_text = "MAX TIER" if tier["next"] is None else f"NEXT TIER AT {_card_money(tier['next'])}"
    next_font = _card_font(22)
    draw.text((1000 - _text_width(draw, next_text, next_font), 416), next_text, font=next_font, fill=CARD_MUTED)

    games = int(stats.get("games", 0))
    wins = int(stats.get("wins", 0))
    losses = int(stats.get("losses", 0))
    _metric_box(draw, (80, 472, 526, 610), "All-time wager", _card_money(wager), CARD_PURPLE)
    _metric_box(draw, (554, 472, 1000, 610), "Games played", f"{games:,}", (198, 147, 255))
    _metric_box(draw, (80, 638, 526, 776), "Wins", f"{wins:,}", CARD_GREEN)
    _metric_box(draw, (554, 638, 1000, 776), "Losses", f"{losses:,}", CARD_RED)

    win_rate = (wins / games * 100) if games else 0.0
    draw.text((80, 824), "WIN RATE", font=_card_font(26), fill=CARD_MUTED)
    rate_text = f"{win_rate:.1f}%"
    rate_font = _card_font(30, True)
    rate_color = CARD_GREEN if win_rate >= 50 else CARD_RED
    draw.text((1000 - _text_width(draw, rate_text, rate_font), 818), rate_text, font=rate_font, fill=rate_color)
    draw.rounded_rectangle((80, 866, 1000, 888), radius=11, fill=(43, 23, 76))
    rate_width = int(920 * min(100.0, max(0.0, win_rate)) / 100)
    if rate_width:
        draw.rounded_rectangle((80, 866, 80 + rate_width, 888), radius=11, fill=rate_color)
    footer = "CASINO ROYALS  •  TRANSPARENT TELEGRAM GAMES"
    footer_font = _card_font(21)
    draw.text(((1080 - _text_width(draw, footer, footer_font)) / 2, 992), footer, font=footer_font, fill=(125, 111, 157))
    output = io.BytesIO()
    image.save(output, format="PNG", optimize=True)
    return output.getvalue()


def render_leaderboard_card_png(leaders: Sequence[Mapping[str, Any]]) -> bytes:
    image, draw = _new_card_canvas()
    draw.text((42, 40), "TOP WAGER", font=_card_font(56, True), fill=CARD_PURPLE)
    draw.text((42, 108), "Top 10 lifetime — ranked by total settled wager", font=_card_font(25), fill=CARD_MUTED)
    draw.line((42, 166, 1038, 166), fill=CARD_PURPLE_SOFT, width=2)
    rank_colors = {1: CARD_GOLD, 2: (212, 211, 225), 3: (230, 139, 76)}
    for index in range(1, 11):
        player = leaders[index - 1] if index <= len(leaders) else None
        y1 = 194 + (index - 1) * 76
        y2 = y1 + 64
        draw.rounded_rectangle((24, y1, 1056, y2), radius=17, fill=(48, 25, 83) if index <= 3 else CARD_BOX)
        accent = rank_colors.get(index, (173, 154, 218))
        draw.text((52, y1 + 13), f"{index}.", font=_card_font(31, True), fill=accent)
        if player is None:
            draw.text((122, y1 + 15), "—", font=_card_font(28), fill=(90, 77, 117))
            continue
        name = f"@{player['username']}" if player.get("username") else str(player.get("first_name") or f"Player {player['user_id']}")
        name_font = _card_font(31, index <= 3)
        draw.text((122, y1 + 13), _fit_card_text(draw, name, name_font, 570), font=name_font, fill=CARD_TEXT)
        amount = _card_money(player.get("total_wager", 0))
        amount_font = _card_font(31, True)
        draw.text((1024 - _text_width(draw, amount, amount_font), y1 + 13), amount, font=amount_font, fill=CARD_PURPLE if index <= 3 else CARD_TEXT)
    draw.text((42, 992), "Only completed bets count • Wallet balances remain private", font=_card_font(20), fill=CARD_MUTED)
    output = io.BytesIO()
    image.save(output, format="PNG", optimize=True)
    return output.getvalue()


# ---------------------------------------------------------------------------
# Shared helpers and typed user-facing errors
# ---------------------------------------------------------------------------

class GameError(Exception):
    """An expected validation/state error safe to display to a user."""


class InsufficientBalance(GameError):
    """Raised when an atomic ledger operation lacks available funds."""


class InvalidState(GameError):
    """Raised when a challenge, deposit, or withdrawal state is invalid."""


def utc_now() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")


def parse_utc(value: str) -> datetime:
    return datetime.strptime(value, "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)


def quantize_money(value: Union[str, int, float, Decimal]) -> Decimal:
    try:
        result = Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError) as exc:
        raise GameError("Please enter a valid number.") from exc
    if not result.is_finite():
        raise GameError("Please enter a finite number.")
    result = result.quantize(MONEY_QUANTUM, rounding=ROUND_HALF_UP)
    if abs(result) > MAX_LEDGER_AMOUNT:
        raise GameError("That amount is outside the supported range.")
    return result


def parse_positive_amount(raw: str, label: str = "amount") -> Decimal:
    value = quantize_money(raw.strip())
    if value <= 0:
        raise GameError(f"The {label} must be greater than zero.")
    return value


def amount_float(value: Union[str, int, float, Decimal]) -> float:
    return float(quantize_money(value))


def fmt_amount(value: Union[str, int, float, Decimal]) -> str:
    number = quantize_money(value)
    if number == 0:
        number = Decimal("0.00")
    rendered = f"{number:.2f}".rstrip("0").rstrip(".")
    return rendered or "0"


def number_emoji(number: int) -> str:
    """Render outcomes as plain digits so the numeric result stays transparent."""
    return str(int(number))


def normalize_currency(raw: Optional[str]) -> str:
    if not raw:
        return "COIN"
    value = raw.strip().lower()
    if value in {"coin", "coins"}:
        return "COIN"
    if value in {"usdt", "usd", "$"}:
        return "USDT"
    raise GameError("Currency must be Coins or USDT.")


def coins_from_usdt(usdt_amount: Decimal, rate: Decimal) -> Decimal:
    return (usdt_amount * rate).quantize(MONEY_QUANTUM, rounding=ROUND_HALF_UP)


def usdt_from_coins(coin_amount: Union[str, int, float, Decimal], rate: Decimal) -> Decimal:
    if rate <= 0:
        raise GameError("USDT conversion rate is invalid.")
    return (quantize_money(coin_amount) / rate).quantize(MONEY_QUANTUM, rounding=ROUND_HALF_UP)


def format_coin_with_usdt(
    coin_amount: Union[str, int, float, Decimal],
    rate: Decimal,
) -> str:
    return f"{fmt_amount(coin_amount)} Coins (≈ {fmt_amount(usdt_from_coins(coin_amount, rate))} USDT)"


def player_tier(total_wager: Union[str, int, float, Decimal]) -> Dict[str, Any]:
    wager = quantize_money(total_wager)
    tiers = (
        ("NOVICE", Decimal("0"), Decimal("10000")),
        ("BRONZE", Decimal("10000"), Decimal("50000")),
        ("SILVER", Decimal("50000"), Decimal("100000")),
        ("GOLD", Decimal("100000"), Decimal("250000")),
        ("DIAMOND", Decimal("250000"), Decimal("500000")),
        ("ROYAL", Decimal("500000"), None),
    )
    for name, start, end in tiers:
        if end is None or wager < end:
            progress = Decimal("1") if end is None else (wager - start) / (end - start)
            return {
                "name": name,
                "next": end,
                "progress": max(0.0, min(1.0, float(progress))),
            }
    return {"name": "ROYAL", "next": None, "progress": 1.0}


def format_bet(challenge: Mapping[str, Any]) -> str:
    currency = str(challenge.get("display_currency") or "COIN").upper()
    if currency == "USDT":
        display_bet = challenge.get("display_bet")
        if display_bet is None:
            rate = quantize_money(challenge.get("conversion_rate") or "98")
            display_bet = usdt_from_coins(challenge["bet"], rate)
        return f"{fmt_amount(display_bet)} USDT ({fmt_amount(challenge['bet'])} Coins)"
    return f"{fmt_amount(challenge['bet'])} Coins"


def is_owner(user_id: Optional[int]) -> bool:
    return bool(user_id is not None and user_id in OWNER_IDS)


def is_admin(user_id: Optional[int]) -> bool:
    return bool(user_id is not None and user_id in ADMIN_IDS)


def styled_button(
    text: str,
    callback_data: Optional[str] = None,
    *,
    style: Optional[str] = None,
    icon_key: Optional[str] = None,
    url: Optional[str] = None,
) -> InlineKeyboardButton:
    kwargs: Dict[str, Any] = {"text": text}
    if callback_data is not None:
        kwargs["callback_data"] = callback_data
    elif url is not None:
        kwargs["url"] = url
    else:
        raise ValueError("A callback_data or URL is required")
    if style:
        kwargs["style"] = style
    if icon_key and icon_key in BUTTON_CUSTOM_EMOJI_IDS:
        kwargs["icon_custom_emoji_id"] = BUTTON_CUSTOM_EMOJI_IDS[icon_key]
    return InlineKeyboardButton(**kwargs)


def display_name(user: Mapping[str, Any]) -> str:
    username = (user.get("username") or "").strip()
    if username:
        return f"@{html.escape(username)}"
    first_name = (user.get("first_name") or "").strip() or f"Player {user['user_id']}"
    return f'<a href="tg://user?id={int(user["user_id"])}">{html.escape(first_name)}</a>'


def plain_display_name(user: Mapping[str, Any]) -> str:
    username = (user.get("username") or "").strip()
    if username:
        return f"@{username}"
    return (user.get("first_name") or "").strip() or f"Player {user['user_id']}"


def masked_winner_name(user: Mapping[str, Any], is_house: bool = False) -> str:
    if is_house:
        return "@CasinoRoyalsBot"
    username = (user.get("username") or "").strip()
    if username:
        if len(username) <= 2:
            masked = username[:1] + "***"
        elif len(username) <= 4:
            masked = username[:1] + "***" + username[-1:]
        else:
            masked = username[:2] + "***" + username[-2:]
        return f"@{masked}"
    user_id = str(user.get("user_id") or "")
    return f"Player ***{user_id[-3:]}"


def user_from_telegram(tg_user: Any) -> Dict[str, Any]:
    return {
        "user_id": int(tg_user.id),
        "username": tg_user.username or "",
        "first_name": tg_user.first_name or "",
        "is_bot": bool(tg_user.is_bot),
    }


def make_txn_id(prefix: str) -> str:
    return f"{prefix}-{datetime.now(timezone.utc):%Y%m%d}-{uuid.uuid4().hex[:12].upper()}"


