CHANNEL_SETTING_LABELS = {
    "required_chat_invite_link": ("Play Group Invite Link", "https://t.me/+XXXXXXXX"),
    "optional_channel_invite_link": ("News Channel Invite Link", "https://t.me/ChannelName"),
    "official_channel_username": ("Official Channel Username", "@MyChannel"),
    "logs_channel_username": ("Logs Channel Username", "@MyLogsChannel"),
    "logs_channel_id": ("Logs Channel ID", "-1001234567890"),
}


def validate_channel_setting(key: str, value: str) -> Optional[str]:
    if key.endswith("_link"):
        if value and not value.startswith("https://t.me/"):
            return "Enter a valid t.me link, e.g. https://t.me/+XXXX or https://t.me/Username."
        return None
    if key.endswith("_username"):
        return None  # the @ prefix is added automatically
    if key == "logs_channel_id":
        if value:
            try:
                int(value)
            except ValueError:
                return "Logs channel ID must be an integer (negative for channels/supergroups)."
        return None
    return "Unknown setting."


