def challenge_text(challenge: Mapping[str, Any], challenger: Mapping[str, Any], opponent: Mapping[str, Any]) -> str:
    bet = quantize_money(challenge["bet"])
    commission = (
        bet * Decimal("2") * quantize_money(challenge.get("commission_percent") or 5)
        / Decimal("100")
    ).quantize(MONEY_QUANTUM, rounding=ROUND_HALF_UP)
    projected_payout = bet * Decimal("2") - commission
    return (
        "🎯 GAME CHALLENGE!\n\n"
        "━━━━━━━━━━━━━━━━━━━━\n\n"
        f"👤 Challenger: {display_name(challenger)}\n\n"
        f"👤 Opponent: {display_name(opponent)}\n\n"
        f"🎮 Game: {html.escape(TELEGRAM_GAMES.get(str(challenge.get('game_type') or 'dice'), TELEGRAM_GAMES['dice'])['name'])}\n\n"
        f"💰 Bet: {format_bet(challenge)}\n"
        f"💎 Projected Commission: {fmt_amount(commission)} Coins\n"
        f"🏆 Projected Winner Payout: {fmt_amount(projected_payout)} Coins\n\n"
        f"⏳ Waiting for {display_name(opponent)} to accept...\n\n"
        "The challenger can select any of the six transparent Telegram games below. "
        "After acceptance, both players manually send one matching Telegram animation."
    )


def game_ready_text(challenge: Mapping[str, Any], challenger: Mapping[str, Any], opponent: Mapping[str, Any]) -> str:
    p1_status = "READY ✅" if challenge.get("challenger_ready") else "Waiting... ⏳"
    p2_status = "READY ✅" if challenge.get("opponent_ready") else "Waiting... ⏳"
    game_key = str(challenge.get("game_type") or "dice")
    game_name = TELEGRAM_GAMES.get(game_key, TELEGRAM_GAMES["dice"])["name"]
    return (
        "✅ CHALLENGE ACCEPTED!\n\n"
        "━━━━━━━━━━━━━━━━━━━━\n\n"
        f"🎮 Game: {html.escape(game_name)}\n\n"
        f"💰 Bet: {format_bet(challenge)}\n\n"
        f"👤 {display_name(challenger)}: {p1_status}\n\n"
        f"👤 {display_name(opponent)}: {p2_status}\n\n"
        "Both players must tap I Am Ready. Then each player manually sends exactly one "
        "matching Telegram animation; the highest returned value wins."
    )


def manual_game_prompt_text(
    challenge: Mapping[str, Any],
    challenger: Mapping[str, Any],
    opponent: Mapping[str, Any],
) -> str:
    game_key = str(challenge.get("game_type") or "dice")
    game = TELEGRAM_GAMES.get(game_key, TELEGRAM_GAMES["dice"])
    return (
        "🎮 <b>MANUAL TELEGRAM GAME READY</b>\n\n"
        "━━━━━━━━━━━━━━━━━━━━\n\n"
        f"Game: <b>{html.escape(str(game['name']))}</b> {game['emoji']}\n"
        f"Bet Secured: <b>{format_bet(challenge)} from each player</b>\n"
        f"Value Range: <b>1–{int(game['max_value'])}</b>\n\n"
        f"1. {display_name(challenger)} sends exactly one <b>{game['emoji']}</b> animation.\n"
        f"2. {display_name(opponent)} sends exactly one <b>{game['emoji']}</b> animation.\n"
        "3. The bot records both Telegram values and message IDs.\n"
        "4. Highest value wins; on a tie, both players manually send one new animation.\n\n"
        "Only live, non-forwarded animations from these two players in this group count. "
        f"Send within {MANUAL_ROLL_TTL_SECONDS // 60} minutes or both stakes are refunded."
    )


def dice_roll_text(
    challenger: Mapping[str, Any],
    opponent: Mapping[str, Any],
    p1_rolls: Sequence[int],
    p2_rolls: Sequence[int],
) -> str:
    lines = ["🎲 ROLLING...", "", "━━━━━━━━━━━━━━━━━━━━", "", f"⚡ {display_name(challenger)}:", ""]
    for index, value in enumerate(p1_rolls, 1):
        lines.extend([f"   Dice {index}: {number_emoji(value)}", ""])
    lines.extend([f"   Total: {number_emoji(sum(p1_rolls))}", "", f"⚡ {display_name(opponent)}:", ""])
    for index, value in enumerate(p2_rolls, 1):
        lines.extend([f"   Dice {index}: {number_emoji(value)}", ""])
    lines.append(f"   Total: {number_emoji(sum(p2_rolls))}")
    return "\n".join(lines)


def winner_text(
    result: Mapping[str, Any],
    challenger: Mapping[str, Any],
    opponent: Mapping[str, Any],
) -> str:
    p1_id = int(challenge_value(result, "challenger_id"))
    winner = challenger if int(result["winner_id"]) == p1_id else opponent
    loser = opponent if int(result["winner_id"]) == p1_id else challenger
    winner_balance = result["p1_balance"] if int(result["winner_id"]) == p1_id else result["p2_balance"]
    loser_balance = result["p2_balance"] if int(result["winner_id"]) == p1_id else result["p1_balance"]
    currency = str(result.get("display_currency") or "COIN").upper()
    rate = quantize_money(result.get("conversion_rate") or "1")
    if currency == "USDT":
        commission_label = f"{fmt_amount(usdt_from_coins(result['commission'], rate))} USDT ({fmt_amount(result['commission'])} Coins)"
        payout_label = f"{fmt_amount(usdt_from_coins(result['payout'], rate))} USDT ({fmt_amount(result['payout'])} Coins)"
    else:
        commission_label = f"{fmt_amount(result['commission'])} Coins"
        payout_label = f"{fmt_amount(result['payout'])} Coins"
    settlement_note = ""
    if str(result.get("game_mode") or "pvp") == "bot":
        settlement_note = (
            f"\n\n🤖 Bot payout transferred to separate bot wallet <code>{HOUSE_WALLET_USER_ID}</code>."
            if int(result["winner_id"]) == HOUSE_WALLET_USER_ID
            else "\n\n✅ User payout credited directly to the user's Casino Royals wallet."
        )
    source_note = (
        "Source: both players manually sent native Telegram animations; the bot only recorded and compared Telegram's values."
        if str(result.get("fairness_source") or "") == "telegram_user_dice"
        else "Source: Telegram sendDice — values were generated by Telegram, not selected by this bot."
    )
    return (
        "━━━━━━━━━━━━━━━━━━━━\n\n"
        f"🏆 WINNER: {display_name(winner)}!\n\n"
        f"🎮 Game: {html.escape(TELEGRAM_GAMES.get(str(result.get('game_type') or 'dice'), TELEGRAM_GAMES['dice'])['name'])}\n\n"
        f"💰 Bet: {format_bet(result)}\n\n"
        f"💎 Commission ({fmt_amount(result['commission_percent'])}%): {commission_label}\n\n"
        f"🏆 Winner Gets: {payout_label}\n\n"
        f"💳 {display_name(winner)} Balance: {fmt_amount(winner_balance)} Coins (+{fmt_amount(result['payout'])})\n\n"
        f"💳 {display_name(loser)} Balance: {fmt_amount(loser_balance)} Coins (-{fmt_amount(result['bet'])})"
        f"{settlement_note}\n\n"
        f"🔒 Verification: /verify {int(result['game_id'])}\n"
        f"{source_note}"
    )


def challenge_value(mapping: Mapping[str, Any], key: str) -> Any:
    if key not in mapping:
        raise KeyError(f"Missing challenge field: {key}")
    return mapping[key]


