async def tip_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not await require_group(update, "send tips"):
        return
    sender = update.effective_user
    message = update.effective_message
    if sender is None or message is None:
        return
    try:
        replied = message.reply_to_message
        if replied and replied.from_user and not replied.from_user.is_bot:
            if len(context.args) not in (1, 2):
                raise GameError("Reply with <code>/tip amount [coin|usdt]</code>.")
            recipient = await db_call(
                DB.ensure_user,
                int(replied.from_user.id),
                replied.from_user.username or "",
                replied.from_user.first_name or "",
            )
            amount_raw = context.args[0]
            currency = normalize_currency(context.args[1] if len(context.args) == 2 else None)
        else:
            if len(context.args) not in (2, 3) or not context.args[0].startswith("@"):
                raise GameError(
                    "Usage: <code>/tip @username amount [coin|usdt]</code>, or reply with <code>/tip amount</code>."
                )
            recipient = await db_call(DB.find_user_by_username, context.args[0][1:])
            if recipient is None:
                raise GameError("That user is not registered yet.")
            amount_raw = context.args[1]
            currency = normalize_currency(context.args[2] if len(context.args) == 3 else None)
        if int(recipient["user_id"]) == int(sender.id):
            raise GameError("You cannot tip yourself.")
        shown_amount = parse_positive_amount(amount_raw, "tip")
        settings = await db_call(DB.get_settings)
        rate = quantize_money(settings["usdt_inr_rate"])
        coin_amount = (
            coins_from_usdt(shown_amount, rate)
            if currency == "USDT" else shown_amount
        )
        if coin_amount < MONEY_QUANTUM:
            raise GameError("Tip is too small.")
        result = await db_call(
            DB.transfer_tip,
            int(sender.id),
            int(recipient["user_id"]),
            coin_amount,
            currency,
            shown_amount,
            rate if currency == "USDT" else Decimal("1"),
        )
        sender_row = await db_call(DB.get_user, int(sender.id))
        unit = "USDT" if currency == "USDT" else "Coins"
        await message.reply_text(
            "🎁 <b>TIP SENT</b>\n\n"
            f"From: {display_name(sender_row)}\n"
            f"To: {display_name(recipient)}\n"
            f"Tip: <b>{fmt_amount(shown_amount)} {unit}</b>"
            + (f" ({fmt_amount(coin_amount)} Coins)" if currency == "USDT" else "")
            + "\n"
            f"Your Balance: {fmt_amount(result['sender_balance'])} Coins\n"
            f"Reference: <code>{result['reference']}</code>",
            parse_mode=ParseMode.HTML,
        )
        await notify_user(
            context,
            int(recipient["user_id"]),
            "🎁 <b>YOU RECEIVED A TIP</b>\n\n"
            f"From: {display_name(sender_row)}\n"
            f"Amount: {fmt_amount(shown_amount)} {unit}"
            + (f" ({fmt_amount(coin_amount)} Coins)" if currency == "USDT" else "")
            + "\n"
            f"New Balance: {fmt_amount(result['recipient_balance'])} Coins\n"
            f"Reference: <code>{result['reference']}</code>",
        )
    except GameError as exc:
        await message.reply_text(f"❌ {exc}", parse_mode=ParseMode.HTML)


async def stats_text_for(user_id: int) -> str:
    user, rate_raw = await asyncio.gather(
        db_call(DB.get_player_card_stats, user_id),
        db_call(DB.get_setting, "usdt_inr_rate"),
    )
    if user is None:
        raise GameError("User is not registered.")
    games = int(user["games"])
    wins = int(user["wins"])
    losses = int(user["losses"])
    wager = quantize_money(user.get("total_wager", 0))
    win_rate = (wins / games * 100) if games else 0.0
    tier = player_tier(wager)
    filled = int(round(tier["progress"] * 10))
    progress_bar = "█" * filled + "░" * (10 - filled)
    next_tier = "MAX TIER" if tier["next"] is None else f"Next tier at {fmt_amount(tier['next'])} Coins"
    rate = quantize_money(rate_raw)
    return (
        "📊 <b>CASINO ROYALS PLAYER STATS</b>\n\n"
        "━━━━━━━━━━━━━━━━━━━━\n\n"
        f"👤 Player: {display_name(user)}\n"
        f"🏆 Wager Rank: <b>#{user['rank']}</b> of {user['total_users']}\n"
        f"⭐ Tier: <b>{tier['name']}</b>\n"
        f"{progress_bar} {tier['progress'] * 100:.1f}%\n"
        f"{next_tier}\n\n"
        f"💰 All-Time Wager: <b>{fmt_amount(wager)} Coins</b>\n"
        f"🎮 Games Played: {games}\n"
        f"🏆 Wins: {wins}\n"
        f"❌ Losses: {losses}\n"
        f"🎯 Win Rate: {win_rate:.1f}%\n\n"
        f"🪙 Wallet: {fmt_amount(user['balance'])} Coins "
        f"(≈ {fmt_amount(usdt_from_coins(user['balance'], rate))} USDT)\n\n"
        "Only completed games count. Refunded, failed and canceled games are excluded."
    )


async def fetch_profile_avatar(
    context: ContextTypes.DEFAULT_TYPE,
    user_id: int,
) -> Optional[bytes]:
    try:
        photos = await context.bot.get_user_profile_photos(user_id=user_id, limit=1)
        if not photos.photos:
            return None
        file = await context.bot.get_file(photos.photos[0][-1].file_id)
        return bytes(await file.download_as_bytearray())
    except TelegramError as exc:
        LOGGER.info("Could not load profile photo for %s: %s", user_id, exc)
        return None


async def send_stats_card(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    user = update.effective_user
    if user is None:
        return
    if update.callback_query:
        await safe_query_answer(update.callback_query, "Generating stats card...")
    try:
        stats, rate_raw, avatar = await asyncio.gather(
            db_call(DB.get_player_card_stats, int(user.id)),
            db_call(DB.get_setting, "usdt_inr_rate"),
            fetch_profile_avatar(context, int(user.id)),
        )
        if stats is None:
            raise GameError("Player record not found.")
        png = await asyncio.to_thread(
            render_stats_card_png,
            stats,
            avatar,
            quantize_money(rate_raw),
        )
        image = io.BytesIO(png)
        image.name = f"casino_royals_stats_{user.id}.png"
        await update.effective_message.reply_photo(
            photo=image,
            caption=(
                f"📊 <b>{html.escape(plain_display_name(stats))} — Casino Royals Stats</b>\n"
                f"Wager Rank: <b>#{stats['rank']}</b> of {stats['total_users']}\n"
                "Only completed games count."
            ),
            parse_mode=ParseMode.HTML,
        )
    except Exception as exc:
        LOGGER.exception("Could not render stats card")
        await update.effective_message.reply_text(
            await stats_text_for(int(user.id))
            + f"\n\n⚠️ Card fallback: {html.escape(str(exc))}",
            parse_mode=ParseMode.HTML,
        )


