async def leaderboard_text(user_id: Optional[int] = None) -> str:
    leaders = await db_call(DB.leaderboard, 10)
    lines = ["🏆 <b>TOP 10 — ALL-TIME WAGER</b>", "", "━━━━━━━━━━━━━━━━━━━━", ""]
    medals = ["🥇", "🥈", "🥉"]
    if not leaders:
        lines.append("No registered players yet.")
    for rank, player in enumerate(leaders, 1):
        prefix = medals[rank - 1] if rank <= 3 else f"{rank}."
        lines.append(
            f"{prefix} {display_name(player)} — <b>{fmt_amount(player.get('total_wager', 0))} Coins wagered</b> "
            f"· {int(player['wins'])}W/{int(player['losses'])}L"
        )
    if user_id is not None:
        ranking = await db_call(DB.user_wager_rank, user_id)
        if ranking:
            lines.extend([
                "",
                "━━━━━━━━━━━━━━━━━━━━",
                f"👤 Your Wager Rank: <b>#{ranking['rank']}</b> of {ranking['total_users']}",
                f"💰 Your All-Time Wager: <b>{fmt_amount(ranking.get('total_wager', 0))} Coins</b>",
                "Wallet balances are private and never shown on the leaderboard.",
            ])
    return "\n".join(lines)


