async def report_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    user = update.effective_user
    if user is None:
        return
    if len(context.args) < 2 or not context.args[0].isdigit():
        await update.effective_message.reply_text(
            "Usage: <code>/report game_id problem description</code>",
            parse_mode=ParseMode.HTML,
        )
        return
    game_id = int(context.args[0])
    description = " ".join(context.args[1:]).strip()
    try:
        game = await db_call(DB.get_game, game_id)
        if game is None or int(user.id) not in (
            int(game["player1_id"]), int(game["player2_id"])
        ):
            raise GameError("Only a player in this game can report it.")
        feedback = await db_call(
            DB.submit_feedback,
            int(user.id),
            "game_problem",
            description,
            game_id,
            None,
        )
        await update.effective_message.reply_text(
            "✅ <b>GAME REPORT SUBMITTED</b>\n\n"
            f"Game: <code>#{game_id}</code>\n"
            f"Report: <code>#{feedback['id']}</code>\n\n"
            "Your ledger and Telegram result can be checked with /verify.",
            parse_mode=ParseMode.HTML,
        )
    except GameError as exc:
        await update.effective_message.reply_text(f"❌ {exc}")


async def feedback_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    user = update.effective_user
    if query is None or user is None:
        return
    rate_match = re.fullmatch(r"fb:rate:(\d+):([45])", query.data or "")
    problem_match = re.fullmatch(r"fb:problem:(\d+)", query.data or "")
    try:
        if rate_match:
            game_id = int(rate_match.group(1))
            rating = int(rate_match.group(2))
            game = await db_call(DB.get_game, game_id)
            if game is None or int(user.id) not in (
                int(game["player1_id"]), int(game["player2_id"])
            ):
                raise GameError("Only players in this game can rate it.")
            await db_call(
                DB.submit_feedback,
                int(user.id),
                "game_experience",
                "Quick post-game rating",
                game_id,
                rating,
            )
            await safe_query_answer(query, "Thank you for your feedback.", show_alert=True)
        elif problem_match:
            game_id = int(problem_match.group(1))
            game = await db_call(DB.get_game, game_id)
            if game is None or int(user.id) not in (
                int(game["player1_id"]), int(game["player2_id"])
            ):
                raise GameError("Only players in this game can report it.")
            await safe_query_answer(
                query,
                f"Send /report {game_id} followed by the problem description.",
                show_alert=True,
            )
    except GameError as exc:
        await safe_query_answer(query, str(exc), show_alert=True)


