def _json_int_list(raw: Any) -> List[int]:
    try:
        data = json.loads(raw or "[]")
    except (TypeError, json.JSONDecodeError):
        return []
    result: List[int] = []
    if isinstance(data, list):
        for item in data:
            value = item[0] if isinstance(item, list) and item else item
            if isinstance(value, int):
                result.append(value)
    return result


async def verify_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if len(context.args) != 1 or not context.args[0].isdigit():
        await update.effective_message.reply_text(
            "Usage: <code>/verify game_id</code>", parse_mode=ParseMode.HTML
        )
        return
    game_id = int(context.args[0])
    game = await db_call(DB.get_game, game_id)
    if game is None:
        await update.effective_message.reply_text("❌ Game record not found.")
        return
    p1, p2 = await asyncio.gather(
        db_call(DB.get_user, int(game["player1_id"])),
        db_call(DB.get_user, int(game["player2_id"])),
    )
    if p1 is None or p2 is None:
        await update.effective_message.reply_text("❌ Player records are unavailable.")
        return
    game_key = str(game.get("game_type") or "dice")
    config = TELEGRAM_GAMES.get(game_key, TELEGRAM_GAMES["dice"])
    p1_values = _json_int_list(game.get("p1_rolls"))
    p2_values = _json_int_list(game.get("p2_rolls"))
    p1_ids = _json_int_list(game.get("p1_message_ids"))
    p2_ids = _json_int_list(game.get("p2_message_ids"))
    maximum = int(config["max_value"])
    integrity = bool(
        game["status"] == "completed"
        and p1_values and len(p1_values) == len(p2_values)
        and len(p1_ids) == len(p1_values)
        and len(p2_ids) == len(p2_values)
        and all(1 <= value <= maximum for value in p1_values + p2_values)
        and p1_values[-1] != p2_values[-1]
    )
    expected_winner: Optional[int] = None
    if p1_values and p2_values and p1_values[-1] != p2_values[-1]:
        expected_winner = (
            int(game["player1_id"])
            if p1_values[-1] > p2_values[-1] else int(game["player2_id"])
        )
        integrity = integrity and expected_winner == int(game["winner_id"] or 0)
    gross = quantize_money(game["bet"]) * Decimal("2")
    expected_commission = (
        gross * quantize_money(game["commission_percent"]) / Decimal("100")
    ).quantize(MONEY_QUANTUM, rounding=ROUND_HALF_UP)
    integrity = integrity and quantize_money(game["commission"]) == expected_commission

    rounds: List[str] = []
    for index, (left, right) in enumerate(zip(p1_values, p2_values), 1):
        left_id = p1_ids[index - 1] if index <= len(p1_ids) else 0
        right_id = p2_ids[index - 1] if index <= len(p2_ids) else 0
        rounds.append(
            f"Round {index}: {display_name(p1)} <b>{describe_game_value(game_key, left)}</b> "
            f"(<code>{left_id}</code>) vs {display_name(p2)} <b>{describe_game_value(game_key, right)}</b> "
            f"(<code>{right_id}</code>)"
        )
    winner_id = int(game.get("winner_id") or 0)
    if winner_id == int(p1["user_id"]):
        winner_text_value = display_name(p1)
    elif winner_id == int(p2["user_id"]):
        winner_text_value = display_name(p2)
    else:
        winner_text_value = "Not settled"
    text = (
        "🔒 <b>GAME VERIFICATION</b>\n\n"
        f"Game ID: <code>#{game_id}</code>\n"
        f"Type: {html.escape(str(config['name']))}\n"
        f"Mode: {'User vs Bot' if str(game.get('game_mode') or 'pvp') == 'bot' else 'Player vs Player'}\n"
        f"Status: {html.escape(str(game['status']))}\n"
        f"Range: 1–{maximum}\n"
        f"Source: <code>{html.escape(str(game.get('fairness_source') or 'telegram_user_dice'))}</code>\n\n"
        + ("\n".join(rounds) if rounds else "No completed rounds recorded.")
        + "\n\n"
        f"Winner: {winner_text_value}\n"
        f"Bet: {format_bet(game)} each\n"
        f"Commission: {fmt_amount(game['commission'])} Coins\n"
        f"Completed: {html.escape(str(game.get('completed_at') or 'N/A'))}\n\n"
        f"Integrity: {'✅ VERIFIED' if integrity else '⚠️ INCOMPLETE OR INVALID'}\n\n"
        "Each number above is the value returned in that Telegram animated-message object; "
        "the IDs identify the corresponding group messages."
    )
    await update.effective_message.reply_text(text, parse_mode=ParseMode.HTML)


async def rematch_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not await require_group(update, "request rematches"):
        return
    if len(context.args) != 1 or not context.args[0].isdigit():
        await update.effective_message.reply_text("Usage: <code>/rematch game_id</code>", parse_mode=ParseMode.HTML)
        return
    user = update.effective_user
    game = await db_call(DB.get_game, int(context.args[0]))
    if game is None or game["status"] != "completed":
        await update.effective_message.reply_text("❌ Completed game not found.")
        return
    if int(user.id) not in (int(game["player1_id"]), int(game["player2_id"])):
        await update.effective_message.reply_text("❌ Only an original player can request this rematch.")
        return
    if str(game.get("game_mode") or "pvp") == "bot":
        await update.effective_message.reply_text(
            "❌ Player-vs-bot mode has been removed. Start a manual PVP game with /play."
        )
        return
    opponent_id = int(game["player2_id"]) if int(user.id) == int(game["player1_id"]) else int(game["player1_id"])
    challenger, opponent = await asyncio.gather(
        db_call(DB.get_user, int(user.id)),
        db_call(DB.get_user, opponent_id),
    )
    try:
        challenge = await db_call(
            DB.create_challenge,
            int(user.id),
            opponent_id,
            quantize_money(game["bet"]),
            int(update.effective_chat.id),
            quantize_money(game["commission_percent"]),
            str(game.get("game_type") or "dice"),
            str(game.get("display_currency") or "COIN"),
            quantize_money(game.get("display_bet") or game["bet"]),
            quantize_money(game.get("conversion_rate") or 1),
        )
        sent = await update.effective_message.reply_text(
            "🔄 <b>REMATCH REQUEST</b>\n\n"
            + challenge_text(challenge, challenger, opponent),
            reply_markup=challenge_keyboard(int(challenge["id"]), str(challenge["game_type"])),
            parse_mode=ParseMode.HTML,
        )
        await db_call(DB.set_challenge_message, int(challenge["id"]), int(sent.message_id))
    except GameError as exc:
        await update.effective_message.reply_text(f"❌ {exc}")


