async def require_group(update: Update, action: str = "play games") -> bool:
    chat = update.effective_chat
    if chat and chat.type in GROUP_TYPES:
        return True
    bot_username = ""
    if update.get_bot() and update.get_bot().username:
        bot_username = update.get_bot().username
    suffix = f"\n\nOpen a group containing @{html.escape(bot_username)}." if bot_username else ""
    if update.callback_query:
        await safe_query_answer(update.callback_query, f"You can only {action} in a group.", show_alert=True)
    elif update.effective_message:
        await update.effective_message.reply_text(
            f"🎲 You can only {html.escape(action)} in a Telegram group.{suffix}",
            parse_mode=ParseMode.HTML,
        )
    return False


def describe_game_value(game_type: str, value: int) -> str:
    """Return a human-auditable description of a Telegram game value."""
    if game_type != "slots":
        return str(value)
    symbols = ("BAR", "GRAPES", "LEMON", "SEVEN")
    raw = value - 1
    reels = [symbols[(raw // divisor) % 4] for divisor in (1, 4, 16)]
    return f"{value} [{' | '.join(reels)}]"


def normalize_game_type(raw: Optional[str]) -> str:
    if not raw:
        return "dice"
    normalized = re.sub(r"[^a-z]", "", raw.lower())
    game_type = GAME_ALIASES.get(normalized)
    if game_type is None:
        choices = ", ".join(TELEGRAM_GAMES)
        raise GameError(f"Unknown game. Choose one of: {choices}.")
    return game_type


def parse_game_options(tokens: Sequence[str]) -> Tuple[str, str]:
    game_type = "dice"
    currency = "COIN"
    game_seen = False
    currency_seen = False
    for raw in tokens:
        normalized = re.sub(r"[^a-z$]", "", raw.lower())
        if normalized in {"usdt", "usd", "$", "coin", "coins", "inr", "rs"}:
            if currency_seen:
                raise GameError("Specify the bet currency only once.")
            currency = normalize_currency(normalized)
            currency_seen = True
        else:
            if game_seen:
                raise GameError("Specify the game only once.")
            game_type = normalize_game_type(raw)
            game_seen = True
    return game_type, currency


async def resolve_opponent(
    update: Update,
    args: Sequence[str],
) -> Tuple[Dict[str, Any], str, str, str]:
    message = update.effective_message
    if message is None:
        raise GameError("Message context is unavailable.")
    replied = message.reply_to_message
    if replied and replied.from_user and not replied.from_user.is_bot:
        parts = list(args[1:]) if args and args[0].startswith("@") else list(args)
        if len(parts) not in (1, 2, 3):
            raise GameError(
                "Reply with <code>/play amount [currency] [game]</code> or use "
                "<code>/play @username amount [currency] [game]</code>."
            )
        amount_raw = parts[0]
        game_type, currency = parse_game_options(parts[1:])
        tg = replied.from_user
        opponent = await db_call(DB.ensure_user, int(tg.id), tg.username or "", tg.first_name or "")
        return opponent, amount_raw, game_type, currency

    if len(args) not in (2, 3, 4) or not args[0].startswith("@"):
        raise GameError(
            "Usage: <code>/play @username amount [currency] [game]</code>\n"
            "Or reply with <code>/play amount [currency] [game]</code>."
        )
    username = args[0][1:].strip()
    if not re.fullmatch(r"[A-Za-z0-9_]{3,32}", username):
        raise GameError("Please enter a valid Telegram @username.")
    opponent = await db_call(DB.find_user_by_username, username)
    if opponent is None:
        raise GameError(
            "That user is not registered yet. Ask them to send /start, or reply to one of their group messages with <code>/play amount</code>."
        )
    game_type, currency = parse_game_options(args[2:])
    return opponent, args[1], game_type, currency


async def play_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not await require_group(update, "play games"):
        return
    actor = update.effective_user
    chat = update.effective_chat
    if actor is None or chat is None:
        return
    try:
        opponent, amount_raw, game_type, bet_currency = await resolve_opponent(update, context.args)
        if int(opponent["user_id"]) == int(actor.id):
            raise GameError("You cannot challenge yourself.")
        if opponent.get("is_bot"):
            raise GameError("Bots cannot participate in games.")
        display_bet = parse_positive_amount(amount_raw, "bet")
        settings = await db_call(DB.get_settings)
        usdt_rate = quantize_money(settings["usdt_inr_rate"])
        commission = quantize_money(settings["commission_percent"])
        if bet_currency == "USDT":
            minimum = quantize_money(settings["min_usdt_bet"])
            maximum = quantize_money(settings["max_usdt_bet"])
            if display_bet < minimum or display_bet > maximum:
                raise GameError(
                    f"USDT bet must be between {fmt_amount(minimum)} and {fmt_amount(maximum)} USDT."
                )
            bet = coins_from_usdt(display_bet, usdt_rate)
            conversion_rate = usdt_rate
        else:
            minimum = quantize_money(settings["min_bet"])
            maximum = quantize_money(settings["max_bet"])
            if display_bet < minimum or display_bet > maximum:
                raise GameError(
                    f"Bet must be between {fmt_amount(minimum)} and {fmt_amount(maximum)} Coins."
                )
            bet = display_bet
            conversion_rate = Decimal("1")

        # Validate group membership when Telegram permits getChatMember for this bot.
        try:
            member = await context.bot.get_chat_member(int(chat.id), int(opponent["user_id"]))
            if member.status in (ChatMemberStatus.LEFT, ChatMemberStatus.BANNED):
                raise GameError("The opponent is not a member of this group.")
            if member.user.is_bot:
                raise GameError("Bots cannot participate in games.")
            opponent = await db_call(
                DB.ensure_user,
                int(member.user.id),
                member.user.username or "",
                member.user.first_name or "",
            )
        except GameError:
            raise
        except (BadRequest, Forbidden) as exc:
            # Telegram only guarantees getChatMember for other users when the bot
            # is an administrator. The known registered user is still usable.
            LOGGER.debug("Could not verify opponent membership in chat %s: %s", chat.id, exc)

        challenge = await db_call(
            DB.create_challenge,
            int(actor.id),
            int(opponent["user_id"]),
            bet,
            int(chat.id),
            commission,
            game_type,
            bet_currency,
            display_bet,
            conversion_rate,
        )
        challenger = await db_call(DB.get_user, int(actor.id))
        if challenger is None:
            raise GameError("Your account could not be loaded.")
        try:
            sent = await update.effective_message.reply_text(
                challenge_text(challenge, challenger, opponent),
                reply_markup=challenge_keyboard(
                    int(challenge["id"]), str(challenge.get("game_type") or "dice")
                ),
                parse_mode=ParseMode.HTML,
            )
            await db_call(DB.set_challenge_message, int(challenge["id"]), int(sent.message_id))
        except Exception:
            try:
                await db_call(DB.cancel_active, int(actor.id), int(chat.id))
            except Exception:
                LOGGER.exception("Failed to roll back unsent challenge %s", challenge.get("id"))
            raise
    except GameError as exc:
        await update.effective_message.reply_text(f"❌ {exc}", parse_mode=ParseMode.HTML)


async def accept_challenge_flow(
    update: Update,
    context: ContextTypes.DEFAULT_TYPE,
    challenge_id: int,
) -> None:
    actor = update.effective_user
    chat = update.effective_chat
    if actor is None or chat is None:
        return
    challenge = await db_call(DB.accept_challenge, challenge_id, int(actor.id), int(chat.id))
    challenger, opponent = await asyncio.gather(
        db_call(DB.get_user, int(challenge["challenger_id"])),
        db_call(DB.get_user, int(challenge["opponent_id"])),
    )
    if challenger is None or opponent is None:
        raise GameError("A player account could not be loaded.")
    text = manual_game_prompt_text(challenge, challenger, opponent)
    message_id = int(challenge["message_id"] or 0)
    edited = False
    if message_id:
        edited = await safe_edit_text(
            context,
            int(challenge["chat_id"]),
            message_id,
            text,
            None,
        )
    if not edited:
        sent = await context.bot.send_message(
            int(challenge["chat_id"]),
            text,
            parse_mode=ParseMode.HTML,
        )
        await db_call(DB.set_challenge_message, challenge_id, int(sent.message_id))


