async def decline_challenge_flow(
    update: Update,
    context: ContextTypes.DEFAULT_TYPE,
    challenge_id: int,
) -> None:
    actor = update.effective_user
    if actor is None:
        return
    challenge = await db_call(DB.decline_challenge, challenge_id, int(actor.id))
    challenger, opponent = await asyncio.gather(
        db_call(DB.get_user, int(challenge["challenger_id"])),
        db_call(DB.get_user, int(challenge["opponent_id"])),
    )
    if challenger is None or opponent is None:
        raise GameError("A player account could not be loaded.")
    text = (
        "❌ GAME CHALLENGE DECLINED\n\n"
        "━━━━━━━━━━━━━━━━━━━━\n\n"
        f"{display_name(opponent)} declined {display_name(challenger)}'s challenge.\n\n"
        "No coins were deducted."
    )
    if challenge.get("message_id"):
        await safe_edit_text(
            context, int(challenge["chat_id"]), int(challenge["message_id"]), text, None
        )


