async def game_cancel_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    actor = update.effective_user
    chat = update.effective_chat
    if actor is None:
        return
    chat_id = int(chat.id) if chat and chat.type in GROUP_TYPES else None
    try:
        challenge = await db_call(DB.cancel_active, int(actor.id), chat_id)
        challenger, opponent = await asyncio.gather(
            db_call(DB.get_user, int(challenge["challenger_id"])),
            db_call(DB.get_user, int(challenge["opponent_id"])),
        )
        refund_text = "Both stakes were refunded." if challenge.get("refunded") else "No coins were deducted."
        text = (
            "🚫 GAME CANCELED\n\n"
            "━━━━━━━━━━━━━━━━━━━━\n\n"
            f"Canceled by {display_name(await db_call(DB.get_user, int(actor.id)))}.\n\n"
            f"{refund_text}"
        )
        if challenge.get("message_id") and challenge.get("chat_id"):
            await safe_edit_text(
                context, int(challenge["chat_id"]), int(challenge["message_id"]), text, None
            )
        await update.effective_message.reply_text(
            f"✅ Game canceled. {refund_text}", parse_mode=ParseMode.HTML
        )
        for player in (challenger, opponent):
            if player and int(player["user_id"]) != int(actor.id) and challenge.get("refunded"):
                await notify_user(
                    context,
                    int(player["user_id"]),
                    f"🔄 Challenge #{challenge['id']} was canceled and your {fmt_amount(challenge['bet'])}-coin stake was refunded.",
                )
    except GameError as exc:
        await update.effective_message.reply_text(f"❌ {exc}")


