async def game_cancel_callback(
    update: Update,
    context: ContextTypes.DEFAULT_TYPE,
    challenge_id: int,
) -> None:
    query = update.callback_query
    actor = update.effective_user
    chat = update.effective_chat
    if query is None or actor is None or chat is None:
        return
    try:
        current = await db_call(DB.get_challenge, challenge_id)
        if current is None or int(actor.id) not in (
            int(current["challenger_id"]), int(current["opponent_id"])
        ):
            raise InvalidState("You are not a player in this game.")
        if current.get("status") not in ("pending", "selecting"):
            raise InvalidState("This game can no longer be canceled.")
        active = await db_call(DB.find_active_for_user, int(actor.id), int(chat.id))
        if active is None or int(active["id"]) != challenge_id:
            raise InvalidState("This button belongs to an old game.")
        challenge = await db_call(DB.cancel_active, int(actor.id), int(chat.id))
        refund_text = (
            "Both secured stakes were refunded."
            if challenge.get("refunded") else "No coins were deducted."
        )
        await safe_query_answer(query, "Game canceled.")
        await safe_edit_text(
            context,
            int(challenge["chat_id"]),
            int(challenge["message_id"]),
            "🚫 GAME CANCELED\n\n"
            "━━━━━━━━━━━━━━━━━━━━\n\n"
            f"Canceled by {display_name(await db_call(DB.get_user, int(actor.id)))}.\n\n"
            f"{refund_text}",
            None,
        )
    except GameError as exc:
        await safe_query_answer(query, str(exc), show_alert=True)


async def publish_win_log(
    context: ContextTypes.DEFAULT_TYPE,
    result: Mapping[str, Any],
    winner: Mapping[str, Any],
) -> None:
    """Publish a privacy-masked settled-win record to the official logs channel."""
    is_house = (
        str(result.get("game_mode") or "pvp") == "bot"
        and int(result.get("winner_id") or 0) == HOUSE_WALLET_USER_ID
    )
    masked_name = masked_winner_name(winner, is_house=is_house)
    game_key = str(result.get("game_type") or "dice")
    game_name = TELEGRAM_GAMES.get(game_key, TELEGRAM_GAMES["dice"])["name"]
    mode_name = "User vs Bot" if str(result.get("game_mode") or "pvp") == "bot" else "Player vs Player"
    log_text = (
        "🏆 <b>CASINO ROYALS WIN LOG</b>\n\n"
        f"Winner: <b>{html.escape(masked_name)}</b>\n"
        f"Game: {html.escape(str(game_name))}\n"
        f"Mode: {mode_name}\n"
        f"Bet: {format_bet(result)}\n"
        f"Payout: {fmt_amount(result['payout'])} Coins\n"
        f"Game ID: <code>#{result['game_id']}</code>\n\n"
        "Result verified from Telegram animated dice values."
    )
    try:
        await context.bot.send_message(
            LOGS_CHANNEL_ID,
            log_text,
            parse_mode=ParseMode.HTML,
        )
    except TelegramError as exc:
        LOGGER.warning(
            "Could not publish win log to %s (%s): %s",
            LOGS_CHANNEL_USERNAME,
            LOGS_CHANNEL_ID,
            exc,
        )


async def game_ready_callback(
    update: Update,
    context: ContextTypes.DEFAULT_TYPE,
    challenge_id: int,
) -> None:
    if not await require_group(update, "start games"):
        return
    query = update.callback_query
    actor = update.effective_user
    if query is None or actor is None:
        return
    try:
        challenge = await db_call(DB.mark_ready, challenge_id, int(actor.id))
        challenger, opponent = await asyncio.gather(
            db_call(DB.get_user, int(challenge["challenger_id"])),
            db_call(DB.get_user, int(challenge["opponent_id"])),
        )
        if challenger is None or opponent is None:
            raise GameError("A player account could not be loaded.")
        if challenge.get("claimed_roll"):
            await safe_query_answer(
                query,
                "Both players are ready. Send your own Telegram animations now.",
            )
            await safe_edit_text(
                context,
                int(challenge["chat_id"]),
                int(challenge["message_id"]),
                manual_game_prompt_text(challenge, challenger, opponent),
                None,
            )
        else:
            message = "You were already ready." if challenge.get("was_ready") else "Ready status saved."
            await safe_query_answer(query, message)
            await safe_edit_text(
                context,
                int(challenge["chat_id"]),
                int(challenge["message_id"]),
                game_ready_text(challenge, challenger, opponent),
                ready_keyboard(challenge_id),
            )
    except GameError as exc:
        await safe_query_answer(query, str(exc), show_alert=True)
    except TelegramError:
        LOGGER.exception("Telegram error while running transparent game %s", challenge_id)
        try:
            await context.bot.send_message(
                update.effective_chat.id,
                "⚠️ Telegram could not complete the animations. Stakes remain protected; "
                "an automatic timeout refund applies if settlement did not complete.",
            )
        except TelegramError:
            LOGGER.debug("Could not send transparent-game recovery notice")
        raise


async def manual_game_roll_handler(
    update: Update,
    context: ContextTypes.DEFAULT_TYPE,
) -> None:
    """Use player-sent native Telegram animations as the PVP game source."""
    message = update.effective_message
    user = update.effective_user
    chat = update.effective_chat
    if (
        message is None
        or message.dice is None
        or user is None
        or user.is_bot
        or chat is None
        or chat.type not in GROUP_TYPES
    ):
        return

    active = await db_call(DB.find_active_for_user, int(user.id), int(chat.id))
    if (
        active is None
        or str(active.get("status")) != "rolling"
        or str(active.get("game_mode") or "pvp") != "pvp"
    ):
        return
    if getattr(message, "forward_origin", None) is not None:
        await message.reply_text(
            "❌ Forwarded animations do not count. Send a new live Telegram game animation."
        )
        return

    try:
        result = await db_call(
            DB.record_manual_roll,
            int(user.id),
            int(chat.id),
            str(message.dice.emoji),
            int(message.dice.value),
            int(message.message_id),
        )
    except GameError as exc:
        await message.reply_text(f"❌ {exc}")
        return
    if not result.get("accepted"):
        reason = str(result.get("reason") or "")
        if reason == "no_game":
            return
        if reason == "wrong_game":
            await message.reply_text(
                "❌ Wrong animation for this game. Send exactly one "
                f"{result['expected_emoji']} ({html.escape(str(result['expected_game']))}).",
                parse_mode=ParseMode.HTML,
            )
        elif reason in {"already_rolled", "duplicate_message"}:
            await message.reply_text(
                "⏳ Your animation for this round is already recorded. "
                "Wait for the other player."
            )
        return

    challenger, opponent = await asyncio.gather(
        db_call(DB.get_user, int(result["challenger_id"])),
        db_call(DB.get_user, int(result["opponent_id"])),
    )
    if challenger is None or opponent is None:
        LOGGER.error("Manual game %s player row missing after roll", result.get("game_id"))
        return
    game_key = str(result.get("game_type") or "dice")
    config = TELEGRAM_GAMES[game_key]

    if result["status"] == "waiting":
        waiting = challenger if int(result["waiting_for"]) == int(challenger["user_id"]) else opponent
        await message.reply_text(
            "✅ <b>MANUAL RESULT RECORDED</b>\n\n"
            f"Round: <b>{int(result['round_number'])}</b>\n"
            f"Player: {display_name(await db_call(DB.get_user, int(user.id)))}\n"
            f"Telegram Value: <b>{describe_game_value(game_key, int(result['submitted_value']))}</b>\n"
            f"Message ID: <code>{int(result['submitted_message_id'])}</code>\n\n"
            f"Waiting for {display_name(waiting)} to send one {config['emoji']} animation.",
            parse_mode=ParseMode.HTML,
        )
        return

    await asyncio.sleep(float(config["wait"]))
    round_text = (
        "📊 <b>MANUAL TELEGRAM RESULT</b>\n\n"
        f"Round: <b>{int(result['round_number'])}</b>\n"
        f"{display_name(challenger)}: <b>{describe_game_value(game_key, int(result['p1_value']))}</b> "
        f"(<code>{int(result['p1_message_id'])}</code>)\n"
        f"{display_name(opponent)}: <b>{describe_game_value(game_key, int(result['p2_value']))}</b> "
        f"(<code>{int(result['p2_message_id'])}</code>)"
    )
    if result["status"] == "tie":
        await context.bot.send_message(
            int(chat.id),
            round_text
            + "\n\n🤝 <b>TIE</b> — both players must manually send one new "
            + f"{config['emoji']} animation.",
            parse_mode=ParseMode.HTML,
        )
        return

    await context.bot.send_message(
        int(chat.id),
        round_text + "\n\n" + winner_text(result, challenger, opponent),
        parse_mode=ParseMode.HTML,
        reply_markup=feedback_keyboard(int(result["game_id"])),
    )
    winner = (
        challenger
        if int(result["winner_id"]) == int(challenger["user_id"])
        else opponent
    )
    await publish_win_log(context, result, winner)
    if result.get("message_id"):
        await safe_edit_text(
            context,
            int(chat.id),
            int(result["message_id"]),
            "🏁 <b>MANUAL GAME COMPLETED</b>\n\n"
            f"Game: {html.escape(str(config['name']))}\n"
            f"Winner: {display_name(winner)}\n"
            f"Game ID: <code>#{int(result['game_id'])}</code>\n\n"
            f"Verify both player-sent Telegram messages: /verify {int(result['game_id'])}",
            None,
        )


