async def private_chat_redirect(
    update: Update,
    context: ContextTypes.DEFAULT_TYPE,
    action: str,
) -> bool:
    chat = update.effective_chat
    if chat and chat.type == ChatType.PRIVATE:
        return False
    username = context.bot.username or ""
    keyboard = None
    if username:
        keyboard = InlineKeyboardMarkup([[
            styled_button(
                f"Open {action} in Private",
                style="primary",
                icon_key="deposit" if action == "Deposit" else "withdraw",
                url=f"https://t.me/{username}",
            )
        ]])
    if update.callback_query:
        await safe_query_answer(update.callback_query, f"Open a private chat to use {action.lower()}.", show_alert=True)
    if update.effective_message:
        await update.effective_message.reply_text(
            f"🔒 For your privacy, {action.lower()} is available only in a private chat with the bot.",
            reply_markup=keyboard,
        )
    return True


async def deposit_start(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    if await private_chat_redirect(update, context, "Deposit"):
        return ConversationHandler.END
    for key in (
        "deposit_amount", "deposit_network", "deposit_wallet_name",
        "deposit_symbol", "deposit_address", "deposit_instructions",
        "deposit_tx_hash", "deposit_coin_amount", "deposit_rate",
    ):
        context.user_data.pop(key, None)
    wallets = await db_call(DB.list_crypto_wallets, True)
    if not wallets:
        await send_or_edit(
            update,
            "💰 <b>ADD COINS</b>\n\n"
            "No crypto deposit networks are available right now.\n"
            "Contact an administrator to enable a deposit network.",
            back_dashboard_keyboard(),
        )
        return ConversationHandler.END
    await send_or_edit(
        update,
        "💰 <b>ADD COINS</b>\n\n"
        "Select the crypto network you want to deposit with. "
        "Coins are credited at the fixed rate after an administrator verifies the payment.",
        network_selection_keyboard(wallets, "dep:net"),
    )
    return DEP_SELECT_NETWORK


async def deposit_network_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    query = update.callback_query
    if query is None:
        return DEP_SELECT_NETWORK
    match = re.fullmatch(r"dep:net:(\d+)", query.data or "")
    if not match:
        await safe_query_answer(query, "Invalid deposit method.", show_alert=True)
        return DEP_SELECT_NETWORK
    wallet = await db_call(DB.get_crypto_wallet, int(match.group(1)))
    if wallet is None or not int(wallet["enabled"]):
        await safe_query_answer(query, "This deposit network is no longer available.", show_alert=True)
        return DEP_SELECT_NETWORK
    context.user_data["deposit_network"] = str(wallet["network_key"])
    context.user_data["deposit_wallet_name"] = str(wallet["display_name"])
    context.user_data["deposit_symbol"] = str(wallet["coin_symbol"]).upper()
    context.user_data["deposit_address"] = str(wallet["wallet_address"])
    context.user_data["deposit_instructions"] = str(wallet["instructions"] or "")
    minimum = quantize_money(await db_call(DB.get_setting, "min_usdt_deposit"))
    symbol = html.escape(str(context.user_data["deposit_symbol"]))
    await safe_query_answer(query)
    await query.edit_message_text(
        "💎 <b>CRYPTO DEPOSIT</b>\n\n"
        f"Network: <b>{html.escape(str(context.user_data['deposit_wallet_name']))}</b>\n"
        f"Coin: <b>{symbol}</b>\n"
        f"Minimum: <b>{fmt_amount(minimum)} {symbol}</b>\n\n"
        f"Send the {symbol} amount you want to deposit.\n"
        f"Example: <code>{fmt_amount(minimum)}</code>\n\n"
        "Use /cancel to stop.",
        parse_mode=ParseMode.HTML,
    )
    return DEP_AMOUNT_INPUT


async def crypto_deposit_amount_input(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    message = update.effective_message
    if message is None:
        return DEP_AMOUNT_INPUT
    try:
        amount = parse_positive_amount(message.text or "", "deposit amount")
        settings = await db_call(DB.get_settings)
        minimum = quantize_money(settings["min_usdt_deposit"])
        rate = quantize_money(settings["usdt_inr_rate"])
        if amount < minimum:
            raise GameError(
                f"Minimum deposit is {fmt_amount(minimum)} {context.user_data.get('deposit_symbol') or 'USDT'}."
            )
        coin_amount = coins_from_usdt(amount, rate)
        network = str(context.user_data.get("deposit_network") or "")
        address = str(context.user_data.get("deposit_address") or "")
        symbol = str(context.user_data.get("deposit_symbol") or "USDT").upper()
        wallet_name = str(context.user_data.get("deposit_wallet_name") or network)
        instructions = str(context.user_data.get("deposit_instructions") or "")
        if not network or not address:
            raise GameError("Deposit session expired. Start /deposit again.")
        context.user_data["deposit_amount"] = str(amount)
        context.user_data["deposit_coin_amount"] = str(coin_amount)
        context.user_data["deposit_rate"] = str(rate)
        png = await asyncio.to_thread(make_qr_png, address)
        image = io.BytesIO(png)
        image.name = f"casino_royals_crypto_{network}.png"
        instructions_line = (
            f"\n📋 Instructions:\n{html.escape(instructions)}\n" if instructions else "\n"
        )
        await message.reply_photo(
            photo=image,
            caption=(
                "💎 <b>PAY CRYPTO</b>\n\n"
                f"Network: <b>{html.escape(wallet_name)}</b>\n"
                f"Amount: <b>{fmt_amount(amount)} {html.escape(symbol)}</b>\n"
                f"Coin Credit: <b>{fmt_amount(coin_amount)} Coins</b>\n"
                f"Fixed Rate: 1 {html.escape(symbol)} = ₹{fmt_amount(rate)} = {fmt_amount(rate)} Coins\n"
                f"Address:\n<code>{html.escape(address)}</code>\n"
                f"{instructions_line}\n"
                "Scan the QR or copy the address. Send only "
                f"<b>{html.escape(symbol)}</b> on the selected network. "
                "After payment, tap I've Paid."
            ),
            reply_markup=crypto_deposit_keyboard(),
            parse_mode=ParseMode.HTML,
        )
        return DEP_CONFIRM
    except GameError as exc:
        await message.reply_text(f"❌ {exc}\n\nSend another amount or /cancel.")
        return DEP_AMOUNT_INPUT


def normalize_crypto_tx_hash(raw: str) -> str:
    value = raw.strip()
    if "/tx/" in value:
        value = value.rstrip("/").rsplit("/", 1)[-1]
    if not value or len(value) > 128:
        raise GameError("That does not look like a valid transaction hash.")
    if re.fullmatch(r"0x[a-fA-F0-9]{32,128}", value):
        return value
    if re.fullmatch(r"[a-fA-F0-9]{32,128}", value):
        return value
    if re.fullmatch(r"[1-9A-HJ-NP-Za-km-z]{32,128}", value):  # base58 (BTC/LTC/SOL style)
        return value
    raise GameError("Enter a valid transaction hash or an explorer link for the selected network.")


async def crypto_paid_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    query = update.callback_query
    if query is None:
        return DEP_CONFIRM
    if not context.user_data.get("deposit_amount"):
        await safe_query_answer(query, "Crypto deposit session expired.", show_alert=True)
        return ConversationHandler.END
    await safe_query_answer(query)
    await query.edit_message_caption(
        caption=(
            "✅ <b>CRYPTO PAYMENT DETAILS</b>\n\n"
            "Send the blockchain transaction hash now. Explorer links are also accepted."
        ),
        reply_markup=InlineKeyboardMarkup([[
            styled_button("Cancel", "dep:cancel", style="danger", icon_key="back")
        ]]),
        parse_mode=ParseMode.HTML,
    )
    return DEP_TXHASH


async def crypto_tx_hash_input(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    message = update.effective_message
    if message is None:
        return DEP_TXHASH
    try:
        tx_hash = normalize_crypto_tx_hash(message.text or "")
        context.user_data["deposit_tx_hash"] = tx_hash
        await message.reply_text(
            "📷 Send a payment screenshot as a photo or image file for admin review."
        )
        return DEP_SCREENSHOT
    except GameError as exc:
        await message.reply_text(f"❌ {exc}\n\nSend the transaction hash again or /cancel.")
        return DEP_TXHASH


async def crypto_deposit_screenshot(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    message = update.effective_message
    user = update.effective_user
    if message is None or user is None:
        return ConversationHandler.END
    screenshot_id: Optional[str] = None
    screenshot_type = "photo"
    if message.photo:
        screenshot_id = message.photo[-1].file_id
    elif message.document and (message.document.mime_type or "").startswith("image/"):
        screenshot_id = message.document.file_id
        screenshot_type = "document"
    if not screenshot_id:
        await message.reply_text("❌ Send the screenshot as a photo or image document.")
        return DEP_SCREENSHOT
    try:
        network = str(context.user_data.get("deposit_network") or "")
        symbol = str(context.user_data.get("deposit_symbol") or "USDT").upper()
        wallet_name = str(context.user_data.get("deposit_wallet_name") or network)
        amount = quantize_money(context.user_data.get("deposit_amount"))
        coin_amount = quantize_money(context.user_data.get("deposit_coin_amount"))
        rate = quantize_money(context.user_data.get("deposit_rate"))
        tx_hash = str(context.user_data.get("deposit_tx_hash") or "")
        address = str(context.user_data.get("deposit_address") or "")
        if not network or not tx_hash:
            raise GameError("Deposit session expired. Start /deposit again.")
        deposit = await db_call(
            DB.create_deposit,
            int(user.id), amount, coin_amount, rate, screenshot_id,
            screenshot_type, symbol, network, tx_hash, address,
        )
        await message.reply_text(
            "⏳ <b>CRYPTO DEPOSIT SUBMITTED</b>\n\n"
            f"Deposit ID: <code>#{deposit['id']}</code>\n"
            f"Amount: {fmt_amount(amount)} {html.escape(symbol)}\n"
            f"Credit after approval: {fmt_amount(coin_amount)} Coins\n"
            f"Network: {html.escape(wallet_name)}\n"
            f"Transaction: <code>{html.escape(tx_hash)}</code>\n\n"
            "Coins are credited only after administrator verification.",
            parse_mode=ParseMode.HTML,
        )
        depositor = await db_call(DB.get_user, int(user.id))
        caption = (
            "📋 <b>PENDING CRYPTO DEPOSIT</b>\n\n"
            f"Deposit ID: <code>#{deposit['id']}</code>\n"
            f"User: {display_name(depositor)} (<code>{user.id}</code>)\n"
            f"Amount: {fmt_amount(amount)} {html.escape(symbol)}\n"
            f"Credit: {fmt_amount(coin_amount)} Coins\n"
            f"Network: {html.escape(wallet_name)}\n"
            f"TX Hash: <code>{html.escape(tx_hash)}</code>"
        )
        for admin_id in ADMIN_IDS:
            try:
                if screenshot_type == "photo":
                    await context.bot.send_photo(
                        admin_id, screenshot_id, caption=caption,
                        reply_markup=admin_deposit_keyboard(int(deposit["id"])),
                        parse_mode=ParseMode.HTML,
                    )
                else:
                    await context.bot.send_document(
                        admin_id, screenshot_id, caption=caption,
                        reply_markup=admin_deposit_keyboard(int(deposit["id"])),
                        parse_mode=ParseMode.HTML,
                    )
            except TelegramError as exc:
                LOGGER.warning("Could not notify admin about deposit %s: %s", deposit["id"], exc)
        for key in (
            "deposit_amount", "deposit_network", "deposit_wallet_name",
            "deposit_symbol", "deposit_address", "deposit_instructions",
            "deposit_tx_hash", "deposit_coin_amount", "deposit_rate",
        ):
            context.user_data.pop(key, None)
        return ConversationHandler.END
    except GameError as exc:
        await message.reply_text(f"❌ {exc}")
        return DEP_SCREENSHOT


async def crypto_invalid_screenshot(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    await update.effective_message.reply_text(
        "📷 Please send the payment screenshot as a photo or image file, or use /cancel."
    )
