async def deposit_cancel(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    for key in (
        "deposit_amount", "deposit_network", "deposit_wallet_name",
        "deposit_symbol", "deposit_address", "deposit_instructions",
        "deposit_tx_hash", "deposit_coin_amount", "deposit_rate",
    ):
        context.user_data.pop(key, None)
    if update.callback_query:
        await safe_query_answer(update.callback_query, "Deposit canceled.")
        try:
            await update.callback_query.edit_message_caption(
                caption="🚫 Deposit canceled. No request was submitted.",
                reply_markup=back_dashboard_keyboard(),
            )
        except BadRequest:
            await update.callback_query.message.reply_text("🚫 Deposit canceled.")
    elif update.effective_message:
        await update.effective_message.reply_text("🚫 Deposit canceled. No request was submitted.")
    return ConversationHandler.END


