async def maintenance_admin_text() -> str:
    status = await db_call(DB.maintenance_status)
    mode = str(status.get("mode") or "off").upper()
    started = html.escape(str(status.get("started_at") or "Not active"))
    by = html.escape(str(status.get("by") or "N/A"))
    message = html.escape(str(status.get("message") or ""))
    return (
        "⚙️ <b>MAINTENANCE CONTROL</b>\n\n"
        f"Status: <b>{mode}</b>\n"
        f"Started: <code>{started}</code>\n"
        f"Changed By: <code>{by}</code>\n"
        f"Message: {message}\n\n"
        "Enabling maintenance immediately closes pending challenges and refunds "
        "all accepted or rolling games. Admin operations remain available."
    )


async def apply_maintenance_change(
    update: Update,
    context: ContextTypes.DEFAULT_TYPE,
    enabled: bool,
    message: str = "",
) -> List[Dict[str, Any]]:
    events = await db_call(
        DB.set_maintenance_mode,
        enabled,
        int(update.effective_user.id),
        message,
    )
    if not enabled:
        return events
    notified_chats: set[int] = set()
    for event in events:
        refund_line = (
            f"Both secured stakes of {format_bet(event)} each were refunded."
            if event.get("refunded")
            else "The pending challenge was canceled before any stake was deducted."
        )
        text = (
            "⚙️ <b>GAME CLOSED FOR MAINTENANCE</b>\n\n"
            f"Challenge: <code>#{event['id']}</code>\n"
            f"{refund_line}\n\n"
            "No win or loss was recorded."
        )
        if event.get("chat_id") and event.get("message_id"):
            await safe_edit_text(
                context,
                int(event["chat_id"]),
                int(event["message_id"]),
                text,
                None,
            )
        if event.get("chat_id"):
            notified_chats.add(int(event["chat_id"]))
    status = await db_call(DB.maintenance_status)
    for chat_id in notified_chats:
        try:
            await context.bot.send_message(
                chat_id,
                maintenance_user_text(status),
                reply_markup=maintenance_user_keyboard(),
                parse_mode=ParseMode.HTML,
            )
        except TelegramError:
            LOGGER.warning("Could not announce maintenance in chat %s", chat_id)
    return events


async def maintenance_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not await require_admin_update(update):
        return
    action = context.args[0].lower() if context.args else "status"
    if action == "status":
        await update.effective_message.reply_text(
            await maintenance_admin_text(),
            reply_markup=maintenance_admin_keyboard(
                (await db_call(DB.maintenance_status))["mode"]
            ),
            parse_mode=ParseMode.HTML,
        )
        return
    if action not in {"on", "off"}:
        await update.effective_message.reply_text(
            "Usage: <code>/maintenance on [message]</code>, "
            "<code>/maintenance off</code>, or <code>/maintenance status</code>",
            parse_mode=ParseMode.HTML,
        )
        return
    custom_message = " ".join(context.args[1:]).strip() if action == "on" else ""
    events = await apply_maintenance_change(
        update,
        context,
        action == "on",
        custom_message,
    )
    await update.effective_message.reply_text(
        (
            "⚙️ <b>MAINTENANCE ENABLED</b>\n\n"
            f"Closed challenges/games: <b>{len(events)}</b>\n"
            f"Refunded games: <b>{sum(1 for item in events if item.get('refunded'))}</b>"
            if action == "on"
            else "✅ <b>MAINTENANCE DISABLED</b>\n\nCasino Royals is open again."
        ),
        reply_markup=maintenance_admin_keyboard(action),
        parse_mode=ParseMode.HTML,
    )


async def public_bot_funds_text() -> str:
    """Return a safe public snapshot of the separate operational bot reserve."""
    info, settings = await asyncio.gather(
        db_call(DB.get_balance_info, HOUSE_WALLET_USER_ID),
        db_call(DB.get_settings),
    )
    total = max(Decimal("0"), quantize_money(info["balance"]))
    available = max(Decimal("0"), quantize_money(info["available"]))
    usdt_rate = quantize_money(settings["usdt_inr_rate"])
    coin_rate = quantize_money(settings["coin_rate"])
    inr_equivalent = (total * coin_rate).quantize(MONEY_QUANTUM, rounding=ROUND_HALF_UP)
    return (
        "🤖 <b>CASINO ROYALS BOT FUNDS</b>\n\n"
        "━━━━━━━━━━━━━━━━━━━━\n\n"
        f"🪙 Total Bot Reserve: <b>{fmt_amount(total)} Coins</b>\n"
        f"✅ Available Bot Reserve: <b>{fmt_amount(available)} Coins</b>\n\n"
        f"Approximate Value: ₹{fmt_amount(inr_equivalent)} "
        f"· {fmt_amount(usdt_from_coins(total, usdt_rate))} USDT\n"
        f"Live Snapshot: <code>{utc_now()} UTC</code>\n\n"
        "Player-vs-bot betting is disabled. Manual PVP games use the two players' secured stakes, "
        "not this reserve. Owner commission is credited separately and is never included here."
    )


