async def persist_sub_admins() -> None:
    values = sorted(ADMIN_IDS - OWNER_IDS)
    await db_call(DB.set_setting, "sub_admin_ids", ",".join(str(value) for value in values))


async def addadmin_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not await require_owner_update(update):
        return
    if len(context.args) != 1 or not context.args[0].isdigit():
        await update.effective_message.reply_text("Usage: <code>/addadmin user_id</code>", parse_mode=ParseMode.HTML)
        return
    user_id = int(context.args[0])
    if user_id in ADMIN_IDS:
        await update.effective_message.reply_text("That user is already an administrator.")
        return
    await db_call(DB.ensure_user, user_id, "", "Casino Sub-Admin")
    ADMIN_IDS.add(user_id)
    await persist_sub_admins()
    await update.effective_message.reply_text(
        "✅ <b>SUB-ADMIN ADDED</b>\n\n"
        f"User ID: <code>{user_id}</code>\n"
        "Allowed: reviews, withdrawal proofs, broadcasts, bans and feedback.\n"
        "Restricted: crypto wallet management, rates, limits, commission, owner/admin management and manual credits/debits.",
        parse_mode=ParseMode.HTML,
    )
    await notify_user(
        context,
        user_id,
        "👑 You were added as a Casino Royals sub-admin. Use /admin to open the panel.",
    )


async def removeadmin_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not await require_owner_update(update):
        return
    if len(context.args) != 1 or not context.args[0].isdigit():
        await update.effective_message.reply_text("Usage: <code>/removeadmin user_id</code>", parse_mode=ParseMode.HTML)
        return
    user_id = int(context.args[0])
    if user_id in OWNER_IDS:
        await update.effective_message.reply_text("❌ Bot owners cannot be removed at runtime.")
        return
    if user_id not in ADMIN_IDS:
        await update.effective_message.reply_text("That user is not a sub-admin.")
        return
    ADMIN_IDS.discard(user_id)
    await persist_sub_admins()
    await update.effective_message.reply_text(f"✅ Sub-admin <code>{user_id}</code> removed.", parse_mode=ParseMode.HTML)
    await notify_user(context, user_id, "Your Casino Royals sub-admin access was removed.")


