async def backup_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Owner-only: download a full SQLite database backup as a document."""
    if not await require_owner_update(update):
        return
    chat = update.effective_chat
    message = update.effective_message
    if chat is None or message is None:
        return
    if chat.type != ChatType.PRIVATE:
        await message.reply_text(
            "🔒 For security, run <code>/backup</code> in a private chat with the bot.\n"
            "The backup contains every user's balance and all financial records.",
            parse_mode=ParseMode.HTML,
        )
        return
    status_message = await message.reply_text(
        "⏳ Creating database backup...", parse_mode=ParseMode.HTML
    )
    backup_path = os.path.join(
        tempfile.gettempdir(),
        f"casino_royals_backup_{datetime.now(timezone.utc):%Y%m%d_%H%M%S}.db",
    )
    try:
        await asyncio.to_thread(DB.backup_to, backup_path)
        size_kb = os.path.getsize(backup_path) / 1024
        with open(backup_path, "rb") as backup_file:
            await context.bot.send_document(
                chat_id=chat.id,
                document=backup_file,
                filename=os.path.basename(backup_path),
                caption=(
                    "🗄️ <b>DATABASE BACKUP</b>\n\n"
                    f"📦 Size: <b>{size_kb:.1f} KB</b>\n"
                    f"🕒 Taken: <code>{utc_now()} UTC</code>\n\n"
                    "Store this file somewhere safe. It contains every user's balance, "
                    "transaction history and settings.\n"
                    "Restore: stop the bot, replace the database file "
                    "(<code>group_dice_royale.db</code> by default), then start it again."
                ),
                parse_mode=ParseMode.HTML,
            )
        try:
            await status_message.edit_text(
                "✅ Backup created and sent. The temporary file was cleaned up."
            )
        except TelegramError as exc:
            LOGGER.debug("Could not update backup status message: %s", exc)
        LOGGER.info("Owner %s downloaded a database backup (%s, %.1f KB)",
                    chat.id, backup_path, size_kb)
    except Exception as exc:
        LOGGER.exception("Database backup failed for owner %s", chat.id)
        try:
            await status_message.edit_text(
                f"❌ Backup failed: {html.escape(str(exc))}", parse_mode=ParseMode.HTML
            )
        except TelegramError:
            pass
    finally:
        try:
            os.remove(backup_path)
        except OSError:
            pass


async def ban_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not await require_admin_update(update):
        return
    message = update.effective_message
    target_id: Optional[int] = None
    reason_parts: List[str] = []
    if message.reply_to_message and message.reply_to_message.from_user:
        target_id = int(message.reply_to_message.from_user.id)
        reason_parts = list(context.args)
    elif context.args and context.args[0].lstrip("-").isdigit():
        target_id = int(context.args[0])
        reason_parts = list(context.args[1:])
    if target_id is None:
        await message.reply_text("Usage: <code>/ban user_id reason</code> or reply with <code>/ban reason</code>.", parse_mode=ParseMode.HTML)
        return
    if target_id in ADMIN_IDS or target_id == HOUSE_WALLET_USER_ID:
        await message.reply_text("❌ Administrators and the bot wallet cannot be banned.")
        return
    reason = " ".join(reason_parts).strip() or "Violation of Casino Royals rules"
    active = await db_call(DB.find_active_for_user, target_id, None)
    if active:
        try:
            if active["status"] == "rolling":
                await db_call(DB.fail_and_refund_game, int(active["id"]), "User banned during active game")
            else:
                await db_call(DB.cancel_active, target_id, None)
        except GameError:
            LOGGER.info("Could not close active game while banning user %s", target_id)
    try:
        result = await db_call(DB.ban_user, target_id, reason, int(update.effective_user.id))
        await message.reply_text(
            "🚫 <b>USER BANNED</b>\n\n"
            f"User: <code>{target_id}</code>\n"
            f"Reason: {html.escape(result['reason'])}",
            parse_mode=ParseMode.HTML,
        )
        await notify_user(context, target_id, f"🚫 You were banned from Casino Royals. Reason: {html.escape(reason)}")
    except GameError as exc:
        await message.reply_text(f"❌ {exc}")


