async def set_numeric_setting(
    update: Update,
    context: ContextTypes.DEFAULT_TYPE,
    key: str,
    label: str,
    *,
    allow_zero: bool = False,
    min_value: Optional[Decimal] = None,
    max_value: Optional[Decimal] = None,
) -> None:
    if not await require_owner_update(update):
        return
    if len(context.args) != 1:
        await update.effective_message.reply_text(f"Usage: <code>/{update.effective_message.text.split()[0].lstrip('/').split('@')[0]} value</code>", parse_mode=ParseMode.HTML)
        return
    try:
        value = quantize_money(context.args[0])
        if (allow_zero and value < 0) or (not allow_zero and value <= 0):
            raise GameError(f"{label} must be {'zero or greater' if allow_zero else 'greater than zero'}.")
        if min_value is not None and value < min_value:
            raise GameError(f"{label} cannot be below {fmt_amount(min_value)}.")
        if max_value is not None and value > max_value:
            raise GameError(f"{label} cannot exceed {fmt_amount(max_value)}.")
        settings = await db_call(DB.get_settings)
        if key == "min_bet" and value > quantize_money(settings["max_bet"]):
            raise GameError("Minimum bet cannot exceed the maximum bet.")
        if key == "max_bet" and value < quantize_money(settings["min_bet"]):
            raise GameError("Maximum bet cannot be below the minimum bet.")
        if key == "min_usdt_bet" and value > quantize_money(settings["max_usdt_bet"]):
            raise GameError("Minimum USDT bet cannot exceed maximum USDT bet.")
        if key == "max_usdt_bet" and value < quantize_money(settings["min_usdt_bet"]):
            raise GameError("Maximum USDT bet cannot be below minimum USDT bet.")
        await db_call(DB.set_setting, key, str(value))
        await update.effective_message.reply_text(f"✅ {label} set to {fmt_amount(value)}.")
    except GameError as exc:
        await update.effective_message.reply_text(f"❌ {exc}")


