async def users_page_text(offset: int) -> Tuple[str, InlineKeyboardMarkup]:
    limit = 20
    users, total = await db_call(DB.users_page, max(0, offset), limit)
    offset = max(0, min(offset, max(0, total - 1))) if total else 0
    lines = [f"👥 <b>ALL USERS</b> ({total})", ""]
    for index, user in enumerate(users, offset + 1):
        lines.append(
            f"{index}. {display_name(user)} · <code>{user['user_id']}</code> · "
            f"{fmt_amount(user['balance'])} Coins · {int(user['wins'])}W/{int(user['losses'])}L"
        )
    if not users:
        lines.append("No registered users.")
    nav: List[InlineKeyboardButton] = []
    if offset > 0:
        nav.append(
            styled_button(
                "Previous",
                f"admin:users:{max(0, offset - limit)}",
                style="primary",
                icon_key="previous",
            )
        )
    if offset + limit < total:
        nav.append(
            styled_button(
                "Next",
                f"admin:users:{offset + limit}",
                style="primary",
                icon_key="next",
            )
        )
    rows: List[List[InlineKeyboardButton]] = []
    if nav:
        rows.append(nav)
    rows.append([styled_button("Back", "admin:panel", style="primary", icon_key="back")])
    return "\n".join(lines), InlineKeyboardMarkup(rows)


async def send_pending_deposits(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if update.effective_chat and update.effective_chat.type != ChatType.PRIVATE:
        await update.effective_message.reply_text("🔒 View deposit screenshots only in a private admin chat.")
        return
    deposits = await db_call(DB.pending_deposits, 20)
    if not deposits:
        await update.effective_message.reply_text("✅ There are no pending deposits.")
        return
    await update.effective_message.reply_text(f"📋 Showing {len(deposits)} pending deposit(s).")
    for deposit in deposits:
        user = await db_call(DB.get_user, int(deposit["user_id"]))
        currency = html.escape(str(deposit.get("currency") or "USDT").upper())
        network = html.escape(str(deposit.get("network") or "N/A"))
        source_line = (
            f"Amount: {fmt_amount(deposit['amount'])} {currency}\n"
            f"Network: {network}\n"
            f"TX Hash: <code>{html.escape(str(deposit.get('tx_hash') or 'N/A'))}</code>\n"
        )
        caption = (
            "📋 <b>PENDING DEPOSIT</b>\n\n"
            f"ID: <code>#{deposit['id']}</code>\n"
            f"User: {display_name(user)} (<code>{deposit['user_id']}</code>)\n"
            f"{source_line}"
            f"Credit: {fmt_amount(deposit['coin_amount'] or deposit['amount'])} Coins\n"
            f"Reference: <code>{html.escape(str(deposit['txn_id']))}</code>"
        )
        try:
            if deposit.get("screenshot_type") == "document":
                await context.bot.send_document(
                    update.effective_chat.id,
                    deposit["screenshot_id"],
                    caption=caption,
                    reply_markup=admin_deposit_keyboard(int(deposit["id"])),
                    parse_mode=ParseMode.HTML,
                )
            else:
                await context.bot.send_photo(
                    update.effective_chat.id,
                    deposit["screenshot_id"],
                    caption=caption,
                    reply_markup=admin_deposit_keyboard(int(deposit["id"])),
                    parse_mode=ParseMode.HTML,
                )
        except TelegramError as exc:
            await update.effective_message.reply_text(
                f"Deposit #{deposit['id']} screenshot could not be displayed: {html.escape(str(exc))}",
                reply_markup=admin_deposit_keyboard(int(deposit["id"])),
                parse_mode=ParseMode.HTML,
            )


async def pending_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not await require_admin_update(update):
        return
    await send_pending_deposits(update, context)


