async def edit_admin_review_message(update: Update, text: str) -> None:
    query = update.callback_query
    if query is None or query.message is None:
        return
    try:
        if query.message.caption is not None:
            await query.edit_message_caption(caption=text, parse_mode=ParseMode.HTML, reply_markup=None)
        else:
            await query.edit_message_text(text=text, parse_mode=ParseMode.HTML, reply_markup=None)
    except BadRequest as exc:
        if "message is not modified" not in str(exc).lower():
            LOGGER.info("Could not update admin review message: %s", exc)


async def deposit_admin_callback(
    update: Update,
    context: ContextTypes.DEFAULT_TYPE,
    action: str,
    deposit_id: int,
) -> None:
    if not await require_admin_update(update):
        return
    query = update.callback_query
    await safe_query_answer(query)
    try:
        if action == "approve":
            deposit = await approve_deposit_action(update, context, deposit_id)
            text = (
                "✅ <b>DEPOSIT APPROVED</b>\n\n"
                f"Deposit #{deposit_id}\n"
                f"Credited {fmt_amount(deposit['coins'])} Coins to <code>{deposit['user_id']}</code>."
            )
        else:
            deposit = await reject_deposit_action(update, context, deposit_id)
            text = f"❌ <b>DEPOSIT REJECTED</b>\n\nDeposit #{deposit_id} for <code>{deposit['user_id']}</code>."
        await edit_admin_review_message(update, text)
    except GameError as exc:
        await safe_query_answer(query, str(exc), show_alert=True)


async def admin_withdraw_proof_entry(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    if not await require_admin_update(update):
        return ConversationHandler.END
    query = update.callback_query
    match = re.fullmatch(r"wdadmin:complete:(\d+)", query.data or "") if query else None
    if not match:
        return ConversationHandler.END
    withdrawal_id = int(match.group(1))
    withdrawal = await db_call(DB.get_withdrawal, withdrawal_id)
    if withdrawal is None:
        await safe_query_answer(query, "Withdrawal not found.", show_alert=True)
        return ConversationHandler.END
    if withdrawal["status"] != "pending":
        await safe_query_answer(
            query,
            f"Withdrawal is already {withdrawal['status']}.",
            show_alert=True,
        )
        return ConversationHandler.END
    context.user_data["withdraw_proof_id"] = withdrawal_id
    context.user_data["withdraw_proof_chat_id"] = int(query.message.chat_id)
    context.user_data["withdraw_proof_message_id"] = int(query.message.message_id)
    context.user_data["withdraw_proof_has_caption"] = query.message.caption is not None
    await safe_query_answer(query, "Send payment screenshot now.")
    prompt = (
        "📷 <b>UPLOAD WITHDRAWAL PAYMENT PROOF</b>\n\n"
        f"Request: <code>#{withdrawal_id}</code>\n"
        f"User: <code>{withdrawal['user_id']}</code>\n\n"
        "Send the completed payment screenshot as a photo or image document. "
        "The wallet debit happens only after the proof is received. Use /cancel to abort."
    )
    try:
        if query.message.caption is not None:
            await query.edit_message_caption(
                caption=prompt, parse_mode=ParseMode.HTML, reply_markup=None
            )
        else:
            await query.edit_message_text(
                text=prompt, parse_mode=ParseMode.HTML, reply_markup=None
            )
    except BadRequest:
        await query.message.reply_text(prompt, parse_mode=ParseMode.HTML)
    return ADM_WAIT_WITHDRAW_PROOF


async def admin_withdraw_proof_received(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    if not await require_admin_update(update):
        return ConversationHandler.END
    message = update.effective_message
    withdrawal_id = context.user_data.get("withdraw_proof_id")
    if message is None or not withdrawal_id:
        return ConversationHandler.END
    proof_file_id: Optional[str] = None
    proof_type = "photo"
    if message.photo:
        proof_file_id = message.photo[-1].file_id
    elif message.document and (message.document.mime_type or "").startswith("image/"):
        proof_file_id = message.document.file_id
        proof_type = "document"
    if not proof_file_id:
        await message.reply_text("❌ Send an image screenshot or use /cancel.")
        return ADM_WAIT_WITHDRAW_PROOF
    try:
        withdrawal = await db_call(
            DB.complete_withdrawal,
            int(withdrawal_id),
            int(update.effective_user.id),
            proof_file_id,
            proof_type,
        )
        payout_label = (
            f"{fmt_amount(withdrawal.get('payout_amount') or 0)} USDT on "
            f"{html.escape(str(withdrawal.get('network') or 'crypto'))}"
        )
        user_caption = (
            "✅ <b>WITHDRAWAL COMPLETED</b>\n\n"
            f"Request ID: <code>#{withdrawal_id}</code>\n"
            f"Paid: <b>{payout_label}</b>\n"
            f"Debited: {fmt_amount(withdrawal['amount'])} Coins\n"
            f"New Balance: {fmt_amount(withdrawal['balance'])} Coins\n"
            f"Reference: <code>{withdrawal['txn_id']}</code>\n\n"
            "Payment proof is attached."
        )
        try:
            if proof_type == "photo":
                await context.bot.send_photo(
                    int(withdrawal["user_id"]),
                    proof_file_id,
                    caption=user_caption,
                    parse_mode=ParseMode.HTML,
                )
            else:
                await context.bot.send_document(
                    int(withdrawal["user_id"]),
                    proof_file_id,
                    caption=user_caption,
                    parse_mode=ParseMode.HTML,
                )
        except TelegramError as exc:
            LOGGER.warning("Withdrawal completed but proof could not reach user %s: %s", withdrawal["user_id"], exc)
        origin_chat = context.user_data.get("withdraw_proof_chat_id")
        origin_message = context.user_data.get("withdraw_proof_message_id")
        completed_text = (
            "✅ <b>WITHDRAWAL COMPLETED WITH PROOF</b>\n\n"
            f"Request: <code>#{withdrawal_id}</code>\n"
            f"User: <code>{withdrawal['user_id']}</code>\n"
            f"Paid: {payout_label}\n"
            f"Reference: <code>{withdrawal['txn_id']}</code>"
        )
        if origin_chat and origin_message:
            try:
                if context.user_data.get("withdraw_proof_has_caption"):
                    await context.bot.edit_message_caption(
                        chat_id=int(origin_chat),
                        message_id=int(origin_message),
                        caption=completed_text,
                        parse_mode=ParseMode.HTML,
                        reply_markup=None,
                    )
                else:
                    await context.bot.edit_message_text(
                        chat_id=int(origin_chat),
                        message_id=int(origin_message),
                        text=completed_text,
                        parse_mode=ParseMode.HTML,
                        reply_markup=None,
                    )
            except TelegramError:
                LOGGER.info("Could not update original withdrawal review message")
        await message.reply_text(
            completed_text,
            reply_markup=admin_panel_keyboard(),
            parse_mode=ParseMode.HTML,
        )
        for key in (
            "withdraw_proof_id", "withdraw_proof_chat_id",
            "withdraw_proof_message_id", "withdraw_proof_has_caption",
        ):
            context.user_data.pop(key, None)
        return ConversationHandler.END
    except GameError as exc:
        await message.reply_text(f"❌ {exc}")
        return ConversationHandler.END


async def admin_withdraw_proof_invalid(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    await update.effective_message.reply_text(
        "📷 Send the completed payment screenshot as a photo or image document, or use /cancel."
    )
    return ADM_WAIT_WITHDRAW_PROOF


async def admin_withdraw_proof_cancel(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    for key in (
        "withdraw_proof_id", "withdraw_proof_chat_id",
        "withdraw_proof_message_id", "withdraw_proof_has_caption",
    ):
        context.user_data.pop(key, None)
    await update.effective_message.reply_text(
        "Withdrawal approval canceled. The request remains pending.",
        reply_markup=admin_panel_keyboard(),
    )
    return ConversationHandler.END


async def withdrawal_admin_callback(
    update: Update,
    context: ContextTypes.DEFAULT_TYPE,
    action: str,
    withdrawal_id: int,
) -> None:
    if not await require_admin_update(update):
        return
    query = update.callback_query
    if action == "complete":
        await safe_query_answer(
            query,
            "Payment proof is required. Reopen the withdrawal button and upload the screenshot.",
            show_alert=True,
        )
        return
    await safe_query_answer(query)
    try:
        withdrawal = await db_call(
            DB.reject_withdrawal, withdrawal_id, int(update.effective_user.id)
        )
        await notify_user(
            context,
            int(withdrawal["user_id"]),
            f"❌ Withdrawal request #{withdrawal_id} was rejected. No coins were debited and the hold was released.",
        )
        text = f"❌ <b>WITHDRAWAL REJECTED</b>\n\nRequest #{withdrawal_id}."
        await edit_admin_review_message(update, text)
    except GameError as exc:
        await safe_query_answer(query, str(exc), show_alert=True)


async def wallet_manager_text() -> str:
    wallets = await db_call(DB.list_crypto_wallets)
    lines = ["💼 <b>CRYPTO WALLET MANAGER</b>\n\n"]
    if not wallets:
        lines.append("No crypto networks configured yet.\n")
    for wallet in wallets:
        status = "🟢 Enabled" if int(wallet["enabled"]) else "🔴 Disabled"
        address = str(wallet["wallet_address"])
        shown = address if len(address) <= 48 else address[:20] + "…" + address[-12:]
        lines.append(
            f"#{wallet['id']} · <b>{html.escape(str(wallet['display_name']))}</b> · {status}\n"
            f"Coin: <b>{html.escape(str(wallet['coin_symbol']))}</b> · "
            f"Key: <code>{html.escape(str(wallet['network_key']))}</code>\n"
            f"Address: <code>{html.escape(shown)}</code>\n"
        )
    lines.append(
        "Changes apply instantly. Users only see enabled networks on the deposit "
        "screen; withdrawal network selection uses the same list."
    )
    return "\n".join(lines)


def _make_wallet_key(display_name: str, taken_keys: Iterable[str]) -> str:
    base = re.sub(r"[^a-z0-9]+", "-", display_name.lower()).strip("-") or "wallet"
    key = base
    suffix = 2
    while key in taken_keys:
        key = f"{base}-{suffix}"
        suffix += 1
    return key


_WALLET_STEP_KEYS = {
    "name": "wallet_name",
    "symbol": "wallet_symbol",
    "address": "wallet_address",
    "instructions": "wallet_instructions",
}
_WALLET_STEP_STATES = {
    "name": WAL_WAIT_NAME,
    "symbol": WAL_WAIT_SYMBOL,
    "address": WAL_WAIT_ADDRESS,
    "instructions": WAL_WAIT_INSTRUCTIONS,
}
_WALLET_NEXT_STEPS = {
    "name": "symbol",
    "symbol": "address",
    "address": "instructions",
}


async def _wallet_prompt_step(
    update: Update,
    context: ContextTypes.DEFAULT_TYPE,
    step: str,
    *,
    editing: bool = False,
) -> None:
    labels = {
        "name": (
            "1/4", "Network display name",
            "Example: <code>USDT TRC20</code>, <code>Bitcoin</code>, <code>SOL</code>",
        ),
        "symbol": (
            "2/4", "Coin symbol",
            "Example: <code>USDT</code>, <code>BTC</code>, <code>ETH</code>",
        ),
        "address": (
            "3/4", "Wallet address",
            "Send the receiving wallet address for this network.",
        ),
        "instructions": (
            "4/4", "Deposit instructions",
            "Example: Send only USDT on the TRON network. Minimum 10 USDT.",
        ),
    }
    number, label, example = labels[step]
    current = context.user_data.get(_WALLET_STEP_KEYS[step])
    if editing and current:
        keep_line = (
            f"\nCurrent: <code>{html.escape(str(current))}</code>\n"
            "Press Skip / Keep to keep it."
        )
    elif step == "instructions":
        keep_line = "\nOptional — press Skip / Keep or send <code>none</code>."
    else:
        keep_line = "\nThis value is required."
    await update.effective_message.reply_text(
        f"💼 <b>{'EDIT' if editing else 'ADD'} CRYPTO NETWORK — STEP {number}</b>\n\n"
        f"{label}:\n{example}\n{keep_line}",
        reply_markup=wallet_conversation_control_keyboard(),
        parse_mode=ParseMode.HTML,
    )


async def _wallet_finish(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    message = update.effective_message
    name = str(context.user_data.get("wallet_name") or "").strip()
    symbol = str(context.user_data.get("wallet_symbol") or "").strip().upper()
    address = str(context.user_data.get("wallet_address") or "").strip()
    instructions = str(context.user_data.get("wallet_instructions") or "").strip()
    editing_id = context.user_data.get("wallet_editing_id")
    try:
        if editing_id:
            wallet = await db_call(
                DB.update_crypto_wallet, int(editing_id),
                display_name=name, coin_symbol=symbol,
                wallet_address=address, instructions=instructions,
            )
            title = "CRYPTO NETWORK UPDATED"
        else:
            taken = {str(item["network_key"]) for item in await db_call(DB.list_crypto_wallets)}
            wallet = await db_call(
                DB.create_crypto_wallet,
                _make_wallet_key(name, taken), name, symbol, address, instructions, True,
            )
            title = "CRYPTO NETWORK ADDED"
    except GameError as exc:
        await message.reply_text(f"❌ {exc}\n\nUse /cancel to stop.")
        return WAL_WAIT_INSTRUCTIONS
    for key in (
        "wallet_editing_id", "wallet_step", "wallet_name", "wallet_symbol",
        "wallet_address", "wallet_instructions",
    ):
        context.user_data.pop(key, None)
    await message.reply_text(
        f"✅ <b>{title}</b>\n\n"
        f"Network: <b>{html.escape(str(wallet['display_name']))}</b>\n"
        f"Coin: <b>{html.escape(str(wallet['coin_symbol']))}</b>\n"
        f"Status: {'🟢 Enabled' if int(wallet['enabled']) else '🔴 Disabled'}\n\n"
        "The change is applied instantly. Users now see this network on the "
        "deposit screen if it is enabled.",
        reply_markup=wallet_manager_keyboard(await db_call(DB.list_crypto_wallets)),
        parse_mode=ParseMode.HTML,
    )
    return ConversationHandler.END


async def _wallet_step_value(
    update: Update,
    context: ContextTypes.DEFAULT_TYPE,
    step: str,
) -> int:
    message = update.effective_message
    raw = (message.text or "").strip() if message else ""
    error: Optional[str] = None
    value = raw
    if step == "name":
        if not value:
            error = "❌ Display name cannot be empty."
        elif len(value) > 64:
            error = "❌ Display name must be 64 characters or fewer."
    elif step == "symbol":
        value = raw.upper()
        if not re.fullmatch(r"[A-Z0-9]{1,12}", value):
            error = "❌ Coin symbol must be 1–12 letters/numbers, e.g. USDT, BTC, SOL."
    elif step == "address":
        try:
            value = validate_crypto_address(raw)
        except GameError as exc:
            error = f"❌ {exc}"
    else:
        value = "" if raw.lower() in ("", "none") else raw
        if len(value) > 1000:
            error = "❌ Instructions must be 1000 characters or fewer."
    if error:
        await message.reply_text(f"{error}\n\nSend it again, press Skip / Keep, or /cancel.")
        return _WALLET_STEP_STATES[step]
    context.user_data[_WALLET_STEP_KEYS[step]] = value
    next_step = _WALLET_NEXT_STEPS.get(step)
    if next_step is None:
        return await _wallet_finish(update, context)
    context.user_data["wallet_step"] = next_step
    editing = bool(context.user_data.get("wallet_editing_id"))
    await _wallet_prompt_step(update, context, next_step, editing=editing)
    return _WALLET_STEP_STATES[next_step]


async def wallet_name_input(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    return await _wallet_step_value(update, context, "name")


