async def wallet_edit_entry(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    if not await require_owner_update(update):
        return ConversationHandler.END
    query = update.callback_query
    match = re.fullmatch(r"wallet:edit:(\d+)", query.data or "") if query else None
    if not match:
        return ConversationHandler.END
    wallet = await db_call(DB.get_crypto_wallet, int(match.group(1)))
    if wallet is None:
        await safe_query_answer(query, "Wallet not found.", show_alert=True)
        return ConversationHandler.END
    context.user_data["wallet_editing_id"] = int(wallet["id"])
    context.user_data["wallet_step"] = "name"
    context.user_data["wallet_name"] = str(wallet["display_name"])
    context.user_data["wallet_symbol"] = str(wallet["coin_symbol"])
    context.user_data["wallet_address"] = str(wallet["wallet_address"])
    context.user_data["wallet_instructions"] = str(wallet["instructions"] or "")
    await safe_query_answer(query)
    await _wallet_prompt_step(update, context, "name", editing=True)
    return WAL_WAIT_NAME


