async def channel_edit_entry(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    if not await require_owner_update(update):
        return ConversationHandler.END
    query = update.callback_query
    match = re.fullmatch(r"admin:ch:edit:([a-z_]+)", query.data or "") if query else None
    if not match:
        return ConversationHandler.END
    key = match.group(1)
    if key not in CHANNEL_SETTING_LABELS:
        await safe_query_answer(query, "Unknown setting.", show_alert=True)
        return ConversationHandler.END
    label, example = CHANNEL_SETTING_LABELS[key]
    current = str(await db_call(DB.get_setting, key) or "")
    context.user_data["ch_edit_key"] = key
    await safe_query_answer(query)
    await query.edit_message_text(
        "🔗 <b>EDIT CHANNEL SETTING</b>\n\n"
        f"{label}:\n"
        f"Current: <code>{html.escape(current) if current else 'Not set'}</code>\n"
        f"Example: <code>{example}</code>\n\n"
        "Send the new value, or send <code>-</code> to clear it. Use /cancel to stop.",
        reply_markup=InlineKeyboardMarkup([[
            styled_button("Cancel", "admin:channels", style="danger", icon_key="back")
        ]]),
        parse_mode=ParseMode.HTML,
    )
    return CH_WAIT_VALUE


async def channel_edit_input(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    message = update.effective_message
    if message is None:
        return CH_WAIT_VALUE
    key = str(context.user_data.get("ch_edit_key") or "")
    if key not in CHANNEL_SETTING_LABELS:
        await message.reply_text("Session expired. Reopen Channel Links from the admin panel.")
        return ConversationHandler.END
    label, _example = CHANNEL_SETTING_LABELS[key]
    value = (message.text or "").strip()
    if value == "-":
        value = ""
    if key.endswith("_username") and value and not value.startswith("@"):
        value = "@" + value
    error = validate_channel_setting(key, value)
    if error:
        await message.reply_text(f"❌ {error}\n\nSend it again or /cancel.")
        return CH_WAIT_VALUE
    await db_call(DB.set_setting, key, value)
    refresh_channel_configuration()
    context.user_data.pop("ch_edit_key", None)
    shown = html.escape(value) if value else "<i>Not set</i>"
    await message.reply_text(
        "✅ <b>CHANNEL SETTING UPDATED</b>\n\n"
        f"{label}: <code>{shown}</code>\n\n"
        "The change is applied instantly — no restart needed.",
        reply_markup=channel_settings_keyboard(),
        parse_mode=ParseMode.HTML,
    )
    return ConversationHandler.END


async def channel_edit_cancel(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    context.user_data.pop("ch_edit_key", None)
    if update.callback_query:
        await safe_query_answer(update.callback_query, "Channel settings closed.")
    if update.effective_message:
        await update.effective_message.reply_text(
            "🚫 Channel settings closed. No changes were saved.",
            reply_markup=channel_settings_keyboard(),
        )
    return ConversationHandler.END


