# ---------------------------------------------------------------------------
# Unified callback router
# ---------------------------------------------------------------------------

async def callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    if query is None:
        return
    data = query.data or ""
    try:
        if data == "membership:check":
            await show_home_callback(update, context)
            return
        if data == "dash:home":
            await show_home_callback(update, context)
            return
        if data == "dash:play":
            await safe_query_answer(query)
            text = (
                "🎲 <b>PLAY A GAME</b>\n\n"
                "Six transparent Telegram games are available in groups:\n"
                "Dice, Darts, Basketball, Football, Bowling and Slots.\n\n"
                "Send: <code>/play @username amount [coin|usdt] [game]</code>\n"
                "Or reply: <code>/play amount [coin|usdt] [game]</code>\n\n"
                "Omit the game to choose it from Premium-icon challenge buttons. Use /games for rules."
            )
            await send_or_edit(update, text, back_dashboard_keyboard())
            return
        if data == "dash:bfunds":
            await send_or_edit(
                update,
                await public_bot_funds_text(),
                bot_funds_keyboard(),
            )
            return
        if data == "dash:fds":
            text, summary = await feedback_stats_text()
            await send_or_edit(
                update,
                text,
                feedback_stats_keyboard(summary),
            )
            return
        if data == "dash:tip":
            await send_or_edit(
                update,
                "🎁 <b>TIP A PLAYER</b>\n\n"
                "Reply to a user's group message with:\n"
                "<code>/tip amount [coin|usdt]</code>\n\n"
                "Or use their username:\n"
                "<code>/tip @username amount [coin|usdt]</code>\n\n"
                "Examples: <code>/tip @player 25</code> or <code>/tip @player 1 usdt</code>. "
                "Tips transfer instantly from available wallet balance and have no commission.",
                back_dashboard_keyboard(),
            )
            return
        if data == "dash:crypto":
            rate = quantize_money(await db_call(DB.get_setting, "usdt_inr_rate"))
            wallets = await db_call(DB.list_crypto_wallets, True)
            if not wallets:
                await send_or_edit(
                    update,
                    "💎 <b>CRYPTO WALLETS</b>\n\nNo crypto networks are currently enabled.",
                    back_dashboard_keyboard(),
                )
                return
            lines = [
                "💎 <b>CRYPTO WALLETS</b>\n\n"
                f"Fixed Rate: 1 USDT = ₹{fmt_amount(rate)} = {fmt_amount(rate)} Coins"
            ]
            for wallet in wallets:
                lines.append(
                    f"\n<b>{html.escape(str(wallet['display_name']))}</b> "
                    f"({html.escape(str(wallet['coin_symbol']))}):\n"
                    f"<code>{html.escape(str(wallet['wallet_address']))}</code>"
                )
            lines.append(
                "\n\nUse /deposit to receive the network QR code and instructions. "
                "Never send assets other than the displayed coin on the selected network."
            )
            await send_or_edit(update, "\n".join(lines), back_dashboard_keyboard())
            return
        if data == "dash:stats":
            await send_stats_card(update, context)
            return
        if data == "dash:leaderboard":
            await send_leaderboard_card(update, context)
            return
        if data == "dash:history":
            if not update.effective_user:
                return
            await send_or_edit(
                update,
                await history_text_for(int(update.effective_user.id)),
                back_dashboard_keyboard(),
            )
            return
        if data == "dash:help":
            user_id = int(update.effective_user.id) if update.effective_user else 0
            await send_or_edit(update, await help_text_for(user_id), back_dashboard_keyboard())
            return
        if data == "dash:deposit":
            await deposit_start(update, context)
            return
        if data == "dash:withdraw":
            await withdraw_start(update, context)
            return

        if data.startswith("fds:"):
            if data == "fds:refresh":
                text, summary = await feedback_stats_text()
                await send_or_edit(
                    update,
                    text,
                    feedback_stats_keyboard(summary),
                )
            elif data == "fds:give":
                await safe_query_answer(query, "Send /feedback followed by your message.")
                await send_or_edit(
                    update,
                    "✉️ <b>GIVE FEEDBACK</b>\n\n"
                    "Send: <code>/feedback your message</code>\n\n"
                    "Your message is visible only to Casino Royals administrators.",
                    back_dashboard_keyboard(),
                )
            else:
                await safe_query_answer(
                    query,
                    "Aggregate feedback total. Individual feedback remains private.",
                )
            return
        if data.startswith("fb:"):
            await feedback_callback(update, context)
            return
        game_match = re.fullmatch(r"game:(accept|decline):(\d+)", data)
        if game_match:
            action, challenge_raw = game_match.groups()
            if action == "accept":
                await game_accept_callback(update, context, int(challenge_raw))
            else:
                await game_decline_callback(update, context, int(challenge_raw))
            return
        mode_match = re.fullmatch(
            r"game:mode:(\d+):(dice|darts|basketball|football|bowling|slots)", data
        )
        if mode_match:
            await game_mode_callback(
                update, context, int(mode_match.group(1)), mode_match.group(2)
            )
            return
        ready_match = re.fullmatch(r"game:ready:(\d+)", data)
        if ready_match:
            await game_ready_callback(update, context, int(ready_match.group(1)))
            return
        cancel_match = re.fullmatch(r"game:cancel:(\d+)", data)
        if cancel_match:
            await game_cancel_callback(update, context, int(cancel_match.group(1)))
            return

        deposit_admin_match = re.fullmatch(r"depadmin:(approve|reject):(\d+)", data)
        if deposit_admin_match:
            await deposit_admin_callback(
                update, context, deposit_admin_match.group(1), int(deposit_admin_match.group(2))
            )
            return
        withdrawal_admin_match = re.fullmatch(r"wdadmin:(complete|reject):(\d+)", data)
        if withdrawal_admin_match:
            await withdrawal_admin_callback(
                update, context, withdrawal_admin_match.group(1), int(withdrawal_admin_match.group(2))
            )
            return

        if data == "admin:panel":
            await admin_panel_callback(update, context)
            return
        if data == "admin:house":
            if not await require_admin_update(update):
                return
            await send_or_edit(update, await house_wallet_text(), admin_back_keyboard())
            return
        if data == "admin:tc":
            if not await require_admin_update(update):
                return
            await send_or_edit(
                update,
                "💎 <b>COMMISSION RANGE</b>\n\n"
                "Use: <code>/tc starting_game_id</code>\n"
                "Example: <code>/tc 100</code>\n\n"
                "Only administrators can view cumulative game commission.",
                admin_back_keyboard(),
            )
            return
        if data == "admin:maintenance":
            if not await require_admin_update(update):
                return
            status = await db_call(DB.maintenance_status)
            await send_or_edit(
                update,
                await maintenance_admin_text(),
                maintenance_admin_keyboard(status["mode"]),
            )
            return
        maintenance_match = re.fullmatch(r"admin:maintenance:(on|off)", data)
        if maintenance_match:
            if not await require_admin_update(update):
                return
            enabled = maintenance_match.group(1) == "on"
            await safe_query_answer(
                query,
                "Enabling maintenance and refunding active games..."
                if enabled
                else "Disabling maintenance...",
            )
            events = await apply_maintenance_change(update, context, enabled)
            await send_or_edit(
                update,
                await maintenance_admin_text()
                + (
                    f"\n\nClosed: <b>{len(events)}</b> · Refunded: "
                    f"<b>{sum(1 for item in events if item.get('refunded'))}</b>"
                    if enabled
                    else "\n\n✅ Casino Royals is open again."
                ),
                maintenance_admin_keyboard("on" if enabled else "off"),
            )
            return
        if data == "admin:stats":
            if not await require_admin_update(update):
                return
            await send_or_edit(update, await admin_stats_text(), admin_back_keyboard())
            return
        users_match = re.fullmatch(r"admin:users:(\d+)", data)
        if users_match:
            if not await require_admin_update(update):
                return
            text, markup = await users_page_text(int(users_match.group(1)))
            await send_or_edit(update, text, markup)
            return
        if data == "admin:settings":
            if not await require_admin_update(update):
                return
            await send_or_edit(update, await settings_text(), admin_back_keyboard())
            return
        if data == "admin:pending":
            if not await require_admin_update(update):
                return
            await safe_query_answer(query)
            await send_pending_deposits(update, context)
            return
        if data == "admin:wallets":
            if not await require_owner_update(update):
                return
            await send_or_edit(
                update,
                await wallet_manager_text(),
                wallet_manager_keyboard(await db_call(DB.list_crypto_wallets)),
            )
            return
        if data == "admin:channels":
            if not await require_owner_update(update):
                return
            await send_or_edit(
                update,
                await channel_settings_text(),
                channel_settings_keyboard(),
            )
            return
        if data == "wallet:list":
            if not await require_owner_update(update):
                return
            await send_or_edit(
                update,
                await wallet_manager_text(),
                wallet_manager_keyboard(await db_call(DB.list_crypto_wallets)),
            )
            return
        wallet_toggle_match = re.fullmatch(r"wallet:toggle:(\d+)", data)
        if wallet_toggle_match:
            if not await require_owner_update(update):
                return
            wallet = await db_call(DB.get_crypto_wallet, int(wallet_toggle_match.group(1)))
            if wallet is None:
                await safe_query_answer(query, "Wallet not found.", show_alert=True)
                return
            new_state = 0 if int(wallet["enabled"]) else 1
            await db_call(DB.update_crypto_wallet, int(wallet["id"]), enabled=new_state)
            await safe_query_answer(
                query,
                f"{wallet['display_name']} is now {'enabled' if new_state else 'disabled'}.",
                show_alert=True,
            )
            await send_or_edit(
                update,
                await wallet_manager_text(),
                wallet_manager_keyboard(await db_call(DB.list_crypto_wallets)),
            )
            return
        wallet_del_match = re.fullmatch(r"wallet:del:(\d+)", data)
        if wallet_del_match:
            if not await require_owner_update(update):
                return
            wallet = await db_call(DB.get_crypto_wallet, int(wallet_del_match.group(1)))
            if wallet is None:
                await safe_query_answer(query, "Wallet not found.", show_alert=True)
                return
            await send_or_edit(
                update,
                "🗑️ <b>DELETE CRYPTO NETWORK?</b>\n\n"
                f"Network: <b>{html.escape(str(wallet['display_name']))}</b> "
                f"({html.escape(str(wallet['coin_symbol']))})\n\n"
                "This removes the wallet from deposits and withdrawals. "
                "Existing deposit/withdrawal history keeps the network name.",
                wallet_delete_confirm_keyboard(int(wallet["id"])),
            )
            return
        wallet_delok_match = re.fullmatch(r"wallet:delok:(\d+)", data)
        if wallet_delok_match:
            if not await require_owner_update(update):
                return
            try:
                await db_call(DB.delete_crypto_wallet, int(wallet_delok_match.group(1)))
            except GameError as exc:
                await safe_query_answer(query, str(exc), show_alert=True)
                return
            await safe_query_answer(query, "Crypto network deleted.", show_alert=True)
            await send_or_edit(
                update,
                await wallet_manager_text(),
                wallet_manager_keyboard(await db_call(DB.list_crypto_wallets)),
            )
            return
        if data in (
            "admin:credit", "admin:debit", "admin:broadcast",
            "admin:housecredit", "admin:housedebit", "wallet:add",
        ) or re.fullmatch(r"wallet:edit:\d+", data) or re.fullmatch(r"admin:ch:edit:[a-z_]+", data):
            # These are normally consumed by the admin/wallet ConversationHandlers.
            # This branch gives a clear recovery message after an application restart.
            await safe_query_answer(query, "Please reopen the admin panel and try again.", show_alert=True)
            return

        if data.startswith("dep:"):
            await safe_query_answer(query, "This deposit session expired. Start again with /deposit.", show_alert=True)
            return
        if data == "noop":
            await safe_query_answer(query)
            return
        await safe_query_answer(query, "This button is no longer active.", show_alert=True)
    except GameError as exc:
        await safe_query_answer(query, str(exc), show_alert=True)
    except Exception:
        LOGGER.exception("Callback routing failed for data=%r", data)
        await safe_query_answer(query, "An unexpected error occurred. Please try again.", show_alert=True)


async def unknown_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    await update.effective_message.reply_text("❓ Unknown command. Use /help to see available commands.")


# ---------------------------------------------------------------------------
# Background maintenance and application lifecycle
# ---------------------------------------------------------------------------

async def recover_orphaned_games(application: Application) -> None:
    """Refund games left in rolling state by a prior crash or forced restart."""
    recovered = await db_call(DB.refund_orphaned_rolling_games)
    for challenge in recovered:
        text = (
            "🔄 <b>GAME RECOVERED AFTER RESTART</b>\n\n"
            f"Challenge #{challenge['id']} was interrupted before settlement. "
            f"Both players received a full refund of {format_bet(challenge)} each.\n\n"
            "No win or loss was recorded."
        )
        if challenge.get("chat_id") and challenge.get("message_id"):
            try:
                await application.bot.edit_message_text(
                    chat_id=int(challenge["chat_id"]),
                    message_id=int(challenge["message_id"]),
                    text=text,
                    parse_mode=ParseMode.HTML,
                    reply_markup=None,
                )
            except TelegramError:
                LOGGER.info("Could not edit recovered game message #%s", challenge["id"])
            try:
                await application.bot.send_message(
                    int(challenge["chat_id"]), text, parse_mode=ParseMode.HTML
                )
            except TelegramError:
                LOGGER.info("Could not announce recovered game #%s", challenge["id"])
    if recovered:
        LOGGER.warning("Recovered and refunded %s orphaned rolling game(s)", len(recovered))


async def cleanup_expired(application: Application) -> None:
    events = await db_call(DB.expire_stale_challenges)
    for challenge in events:
        refund_line = "Both stakes were refunded." if challenge.get("refunded") else "No coins were deducted."
        text = (
            "⌛ GAME EXPIRED\n\n"
            "━━━━━━━━━━━━━━━━━━━━\n\n"
            f"Challenge #{challenge['id']} timed out.\n\n"
            f"{refund_line}"
        )
        if challenge.get("chat_id") and challenge.get("message_id"):
            try:
                await application.bot.edit_message_text(
                    chat_id=int(challenge["chat_id"]),
                    message_id=int(challenge["message_id"]),
                    text=text,
                    reply_markup=None,
                )
            except TelegramError:
                LOGGER.info("Could not edit expired challenge message #%s", challenge["id"])
        if challenge.get("refunded"):
            for user_id in (int(challenge["challenger_id"]), int(challenge["opponent_id"])):
                try:
                    await application.bot.send_message(
                        user_id,
                        f"🔄 Challenge #{challenge['id']} expired. Your {fmt_amount(challenge['bet'])}-coin stake was refunded.",
                    )
                except TelegramError as exc:
                    LOGGER.debug("Could not notify user %s about timeout: %s", user_id, exc)


async def cleanup_loop(application: Application) -> None:
    while True:
        try:
            await cleanup_expired(application)
        except asyncio.CancelledError:
            raise
        except Exception:
            LOGGER.exception("Background challenge cleanup failed")
        await asyncio.sleep(CLEANUP_INTERVAL_SECONDS)


async def validate_premium_button_emojis(application: Application) -> None:
    """Validate configured Premium emoji IDs and disable only invalid mappings."""
    if not PREMIUM_BUTTON_ICONS_ENABLED and not PREMIUM_MESSAGE_EMOJIS_ENABLED:
        LOGGER.info("Premium button and message emoji are disabled by configuration")
        return
    try:
        stickers = await application.bot.get_custom_emoji_stickers(list(PREMIUM_EMOJI_IDS))
    except TelegramError as exc:
        # A transient validation failure must not prevent the bot from starting.
        LOGGER.warning("Could not validate Premium emoji IDs at startup: %s", exc)
        return
    valid_ids = {
        str(sticker.custom_emoji_id)
        for sticker in stickers
        if sticker.custom_emoji_id
    }
    invalid_keys = [
        key for key, emoji_id in BUTTON_CUSTOM_EMOJI_IDS.items()
        if emoji_id not in valid_ids
    ]
    for key in invalid_keys:
        BUTTON_CUSTOM_EMOJI_IDS.pop(key, None)
    invalid_message_fallbacks = [
        fallback for fallback, emoji_id in MESSAGE_PREMIUM_EMOJI_IDS.items()
        if emoji_id not in valid_ids
    ]
    for fallback in invalid_message_fallbacks:
        MESSAGE_PREMIUM_EMOJI_IDS.pop(fallback, None)
    if invalid_keys or invalid_message_fallbacks:
        LOGGER.warning(
            "Disabled invalid Premium mappings: buttons=%s messages=%s",
            ", ".join(sorted(invalid_keys)) or "none",
            len(invalid_message_fallbacks),
        )
    LOGGER.info(
        "Validated %s/%s supplied Premium emoji IDs; %s button roles and %s message emoji enabled",
        len(valid_ids),
        len(PREMIUM_EMOJI_IDS),
        len(BUTTON_CUSTOM_EMOJI_IDS),
        len(MESSAGE_PREMIUM_EMOJI_IDS),
    )


async def validate_required_chat_configuration(application: Application) -> None:
    raw_chat_id = (await db_call(DB.get_setting, "required_chat_id")).strip()
    if not raw_chat_id:
        LOGGER.info(
            "Optional official play group is not bound; manual games remain available in every group."
        )
        return
    try:
        chat_id = int(raw_chat_id)
        chat, bot_member = await asyncio.gather(
            application.bot.get_chat(chat_id),
            application.bot.get_chat_member(chat_id, int(application.bot.id)),
        )
    except (ValueError, TelegramError) as exc:
        LOGGER.warning("Optional play-group configuration is invalid: %s", exc)
        return
    if bot_member.status not in {
        ChatMemberStatus.ADMINISTRATOR,
        ChatMemberStatus.OWNER,
    }:
        LOGGER.error(
            "Bot is not an administrator in optional play group %s; invite metadata may be stale",
            chat_id,
        )
        return
    if chat.title:
        await db_call(DB.set_setting, "required_chat_title", chat.title)
    LOGGER.info("Optional official play group verified: %s (%s)", chat.title, chat_id)


async def validate_logs_channel(application: Application) -> None:
    try:
        chat, member = await asyncio.gather(
            application.bot.get_chat(LOGS_CHANNEL_ID),
            application.bot.get_chat_member(LOGS_CHANNEL_ID, int(application.bot.id)),
        )
        if member.status not in {
            ChatMemberStatus.ADMINISTRATOR,
            ChatMemberStatus.OWNER,
        }:
            LOGGER.warning("Bot is not an administrator in logs channel %s", LOGS_CHANNEL_ID)
        else:
            LOGGER.info("Win logs channel verified: %s (%s)", chat.title, LOGS_CHANNEL_ID)
    except TelegramError as exc:
        LOGGER.warning(
            "Logs channel %s (%s) is unavailable: %s",
            LOGS_CHANNEL_USERNAME,
            LOGS_CHANNEL_ID,
            exc,
        )


async def post_init(application: Application) -> None:
    await validate_premium_button_emojis(application)
    await validate_required_chat_configuration(application)
    await validate_logs_channel(application)
    maintenance = await db_call(DB.maintenance_status)
    if maintenance.get("mode") == "on":
        LOGGER.warning(
            "Casino Royals started in MAINTENANCE mode (set by %s at %s)",
            maintenance.get("by") or "unknown",
            maintenance.get("started_at") or "unknown",
        )
    commands = [
        BotCommand("start", "Open your dashboard"),
        BotCommand("play", "Challenge: /play @user amount game"),
        BotCommand("games", "Show all six manual PVP games"),
        BotCommand("verify", "Verify a completed Telegram game"),
        BotCommand("accept", "Accept your pending challenge"),
        BotCommand("decline", "Decline your pending challenge"),
        BotCommand("balance", "Check Coins and USDT equivalent"),
        BotCommand("bfunds", "View live Casino Royals bot funds"),
        BotCommand("tip", "Tip a player: /tip @user amount"),
        BotCommand("deposit", "Deposit through INR or USDT"),
        BotCommand("withdraw", "Withdraw through INR or USDT"),
        BotCommand("depositstatus", "Track your deposits"),
        BotCommand("withdrawstatus", "Track your withdrawals"),
        BotCommand("stats", "View text game statistics"),
        BotCommand("leaderboard", "Top players by all-time wager"),
        BotCommand("history", "View your last 10 transactions"),
        BotCommand("fairness", "How manual game fairness and refunds work"),
        BotCommand("feedback", "Send feedback to administrators"),
        BotCommand("fds", "View aggregate feedback statistics"),
        BotCommand("cancel", "Cancel the current flow or game"),
        BotCommand("help", "Show help"),
        BotCommand("maintenance", "Admin: pause or resume Casino Royals"),
        BotCommand("tc", "Admin: commission total from a game ID"),
        BotCommand("bindchat", "Admin: bind the optional official play group"),
    ]
    try:
        await application.bot.set_my_commands(commands)
    except TelegramError:
        LOGGER.exception("Could not set bot commands")
    await recover_orphaned_games(application)
    await cleanup_expired(application)
    application.bot_data["cleanup_task"] = asyncio.create_task(
        cleanup_loop(application), name="challenge-cleanup"
    )
    bot = await application.bot.get_me()
    LOGGER.info("Started %s (@%s, id=%s)", BOT_NAME, bot.username, bot.id)


async def post_shutdown(application: Application) -> None:
    task = application.bot_data.get("cleanup_task")
    if task:
        task.cancel()
        try:
            await task
        except asyncio.CancelledError:
            LOGGER.debug("Challenge cleanup task canceled")
    LOGGER.info("Bot shutdown complete")


async def error_handler(update: object, context: ContextTypes.DEFAULT_TYPE) -> None:
    global PREMIUM_MESSAGE_EMOJIS_ENABLED
    error = context.error
    if isinstance(error, ApplicationHandlerStop):
        return
    error_text = str(error).lower()
    premium_entity_error = isinstance(error, BadRequest) and any(
        marker in error_text
        for marker in (
            "custom emoji", "icon_custom_emoji", "button_custom_emoji",
            "button_type_invalid",
        )
    )
    if premium_entity_error and (BUTTON_CUSTOM_EMOJI_IDS or PREMIUM_MESSAGE_EMOJIS_ENABLED):
        BUTTON_CUSTOM_EMOJI_IDS.clear()
        PREMIUM_MESSAGE_EMOJIS_ENABLED = False
        LOGGER.error(
            "Telegram rejected Premium emoji entities; switched to safe text fallback: %s",
            error,
        )
        if isinstance(update, Update) and update.effective_message:
            try:
                await update.effective_message.reply_text(
                    "Premium emoji are unavailable for this bot account. Safe text fallback is now active; repeat the action."
                )
            except TelegramError:
                LOGGER.debug("Could not deliver Premium icon fallback notice")
        return
    LOGGER.error(
        "Unhandled exception while processing update:\n%s",
        "".join(traceback.format_exception(type(error), error, error.__traceback__)),
    )
    if isinstance(update, Update):
        try:
            if update.callback_query:
                await safe_query_answer(
                    update.callback_query,
                    "An unexpected error occurred. Please try again.",
                    show_alert=True,
                )
            elif update.effective_message:
                await update.effective_message.reply_text(
                    "⚠️ An unexpected error occurred. Your ledger remains transactionally protected; check /balance and /history, then try again."
                )
        except TelegramError as exc:
            LOGGER.debug("Could not deliver error notice: %s", exc)


def build_application() -> Application:
    if not BOT_TOKEN:
        raise RuntimeError(
            "TELEGRAM_BOT_TOKEN is not set. Revoke the exposed token in @BotFather, "
            "create a fresh token, then export TELEGRAM_BOT_TOKEN='...'."
        )

    premium_bot = PremiumEmojiExtBot(token=BOT_TOKEN)
    application = (
        ApplicationBuilder()
        .bot(premium_bot)
        .concurrent_updates(False)
        .post_init(post_init)
        .post_shutdown(post_shutdown)
        .build()
    )

    # Registration/onboarding, anti-spam, bans and maintenance execute before features.
    application.add_handler(TypeHandler(Update, ensure_registration), group=-3)
    application.add_handler(MessageHandler(filters.COMMAND, anti_spam_gate), group=-2)
    application.add_handler(TypeHandler(Update, membership_gate), group=-1)

    deposit_conversation = ConversationHandler(
        entry_points=[
            CommandHandler("deposit", deposit_start),
            CallbackQueryHandler(deposit_start, pattern=r"^dash:deposit$"),
        ],
        states={
            DEP_SELECT_NETWORK: [
                CallbackQueryHandler(deposit_network_callback, pattern=r"^dep:net:\d+$"),
                CallbackQueryHandler(deposit_cancel, pattern=r"^dep:cancel$"),
            ],
            DEP_AMOUNT_INPUT: [
                MessageHandler(filters.TEXT & ~filters.COMMAND, crypto_deposit_amount_input),
                CallbackQueryHandler(deposit_cancel, pattern=r"^dep:cancel$"),
            ],
            DEP_CONFIRM: [
                CallbackQueryHandler(crypto_paid_callback, pattern=r"^dep:crypto_paid$"),
                CallbackQueryHandler(deposit_cancel, pattern=r"^dep:cancel$"),
            ],
            DEP_TXHASH: [
                MessageHandler(filters.TEXT & ~filters.COMMAND, crypto_tx_hash_input),
                CallbackQueryHandler(deposit_cancel, pattern=r"^dep:cancel$"),
            ],
            DEP_SCREENSHOT: [
                MessageHandler(filters.PHOTO | filters.Document.IMAGE, crypto_deposit_screenshot),
                CallbackQueryHandler(deposit_cancel, pattern=r"^dep:cancel$"),
                MessageHandler(filters.ALL & ~filters.COMMAND, crypto_invalid_screenshot),
            ],
        },
        fallbacks=[CommandHandler("cancel", deposit_cancel)],
        allow_reentry=True,
        per_chat=True,
        per_user=True,
        per_message=False,
    )

    withdrawal_conversation = ConversationHandler(
        entry_points=[
            CommandHandler("withdraw", withdraw_start),
            CallbackQueryHandler(withdraw_start, pattern=r"^dash:withdraw$"),
        ],
        states={
            WD_WAIT_AMOUNT: [
                MessageHandler(filters.TEXT & ~filters.COMMAND, withdraw_amount_input),
            ],
            WD_SELECT_NETWORK: [
                CallbackQueryHandler(withdraw_network_callback, pattern=r"^wd:network:\d+$"),
            ],
            WD_WAIT_CRYPTO_ADDRESS: [
                MessageHandler(filters.TEXT & ~filters.COMMAND, withdraw_crypto_address_input),
            ],
        },
        fallbacks=[CommandHandler("cancel", withdraw_cancel)],
        allow_reentry=True,
        per_chat=True,
        per_user=True,
        per_message=False,
    )

    admin_conversation = ConversationHandler(
        entry_points=[
            CallbackQueryHandler(admin_credit_entry, pattern=r"^admin:credit$"),
            CallbackQueryHandler(admin_debit_entry, pattern=r"^admin:debit$"),
            CallbackQueryHandler(admin_broadcast_entry, pattern=r"^admin:broadcast$"),
            CallbackQueryHandler(admin_house_credit_entry, pattern=r"^admin:housecredit$"),
            CallbackQueryHandler(admin_house_debit_entry, pattern=r"^admin:housedebit$"),
            CallbackQueryHandler(admin_withdraw_proof_entry, pattern=r"^wdadmin:complete:\d+$"),
        ],
        states={
            ADM_WAIT_CREDIT: [
                MessageHandler(filters.TEXT & ~filters.COMMAND, admin_credit_input),
                CallbackQueryHandler(admin_action_cancel, pattern=r"^admin:panel$"),
            ],
            ADM_WAIT_DEBIT: [
                MessageHandler(filters.TEXT & ~filters.COMMAND, admin_debit_input),
                CallbackQueryHandler(admin_action_cancel, pattern=r"^admin:panel$"),
            ],
            ADM_WAIT_BROADCAST: [
                MessageHandler(filters.TEXT & ~filters.COMMAND, admin_broadcast_input),
                CallbackQueryHandler(admin_action_cancel, pattern=r"^admin:panel$"),
            ],
            ADM_WAIT_HOUSE_CREDIT: [
                MessageHandler(filters.TEXT & ~filters.COMMAND, admin_house_credit_input),
                CallbackQueryHandler(admin_action_cancel, pattern=r"^admin:panel$"),
            ],
            ADM_WAIT_HOUSE_DEBIT: [
                MessageHandler(filters.TEXT & ~filters.COMMAND, admin_house_debit_input),
                CallbackQueryHandler(admin_action_cancel, pattern=r"^admin:panel$"),
            ],
            ADM_WAIT_WITHDRAW_PROOF: [
                MessageHandler(
                    filters.PHOTO | filters.Document.IMAGE,
                    admin_withdraw_proof_received,
                ),
                CommandHandler("cancel", admin_withdraw_proof_cancel),
                MessageHandler(
                    filters.ALL & ~filters.COMMAND,
                    admin_withdraw_proof_invalid,
                ),
            ],
        },
        fallbacks=[CommandHandler("cancel", admin_action_cancel)],
        allow_reentry=True,
        per_chat=True,
        per_user=True,
        per_message=False,
    )

    wallet_conversation = ConversationHandler(
        entry_points=[
            CallbackQueryHandler(wallet_add_entry, pattern=r"^wallet:add$"),
            CallbackQueryHandler(wallet_edit_entry, pattern=r"^wallet:edit:\d+$"),
        ],
        states={
            WAL_WAIT_NAME: [
                MessageHandler(filters.TEXT & ~filters.COMMAND, wallet_name_input),
                CallbackQueryHandler(wallet_skip_callback, pattern=r"^wallet:skip$"),
                CallbackQueryHandler(wallet_cancel_callback, pattern=r"^wallet:cancel$"),
            ],
            WAL_WAIT_SYMBOL: [
                MessageHandler(filters.TEXT & ~filters.COMMAND, wallet_symbol_input),
                CallbackQueryHandler(wallet_skip_callback, pattern=r"^wallet:skip$"),
                CallbackQueryHandler(wallet_cancel_callback, pattern=r"^wallet:cancel$"),
            ],
            WAL_WAIT_ADDRESS: [
                MessageHandler(filters.TEXT & ~filters.COMMAND, wallet_address_input),
                CallbackQueryHandler(wallet_skip_callback, pattern=r"^wallet:skip$"),
                CallbackQueryHandler(wallet_cancel_callback, pattern=r"^wallet:cancel$"),
            ],
            WAL_WAIT_INSTRUCTIONS: [
                MessageHandler(filters.TEXT & ~filters.COMMAND, wallet_instructions_input),
                CallbackQueryHandler(wallet_skip_callback, pattern=r"^wallet:skip$"),
                CallbackQueryHandler(wallet_cancel_callback, pattern=r"^wallet:cancel$"),
            ],
        },
        fallbacks=[CommandHandler("cancel", wallet_cancel_callback)],
        allow_reentry=True,
        per_chat=True,
        per_user=True,
        per_message=False,
    )

    channel_conversation = ConversationHandler(
        entry_points=[
            CallbackQueryHandler(channel_edit_entry, pattern=r"^admin:ch:edit:[a-z_]+$"),
        ],
        states={
            CH_WAIT_VALUE: [
                MessageHandler(filters.TEXT & ~filters.COMMAND, channel_edit_input),
                CallbackQueryHandler(channel_edit_cancel, pattern=r"^admin:channels$"),
            ],
        },
        fallbacks=[CommandHandler("cancel", channel_edit_cancel)],
        allow_reentry=True,
        per_chat=True,
        per_user=True,
        per_message=False,
    )

    application.add_handler(deposit_conversation)
    application.add_handler(withdrawal_conversation)
    application.add_handler(admin_conversation)
    application.add_handler(wallet_conversation)
    application.add_handler(channel_conversation)

    for command, handler in (
        ("start", start_command),
        ("play", play_command),
        ("games", games_command),
        ("verify", verify_command),
        ("accept", accept_command),
        ("decline", decline_command),
        ("balance", balance_command),
        ("bfunds", bfunds_command),
        ("tip", tip_command),
        ("depositstatus", depositstatus_command),
        ("withdrawstatus", withdrawstatus_command),
        ("stats", stats_command),
        ("leaderboard", leaderboard_command),
        ("history", history_command),
        ("feedback", feedback_command),
        ("fds", fds_command),
        ("report", report_command),
        ("fairness", fairness_command),
        ("guide", guide_command),
        ("rematch", rematch_command),
        ("cancel", game_cancel_command),
        ("help", help_command),
        ("admin", admin_panel_command),
        ("admins", admins_command),
        ("backup", backup_command),
        ("addadmin", addadmin_command),
        ("removeadmin", removeadmin_command),
        ("ban", ban_command),
        ("unban", unban_command),
        ("bans", bans_command),
        ("feedbacks", feedbacks_command),
        ("resolvefeedback", resolvefeedback_command),
        ("analytics", analytics_command),
        ("tc", tc_command),
        ("maintenance", maintenance_command),
        ("housewallet", housewallet_command),
        ("housecredit", housecredit_command),
        ("housedebit", housedebit_command),
        ("bindchat", bindchat_command),
        ("setrate", setrate_command),
        ("setusdtrate", setusdtrate_command),
        ("setcommission", setcommission_command),
        ("setminbet", setminbet_command),
        ("setmaxbet", setmaxbet_command),
        ("setusdtmindeposit", setusdtmindeposit_command),
        ("setusdtminwithdraw", setusdtminwithdraw_command),
        ("setusdtminbet", setusdtminbet_command),
        ("setusdtmaxbet", setusdtmaxbet_command),
        ("credit", credit_command),
        ("debit", debit_command),
        ("broadcast", broadcast_command),
        ("pending", pending_command),
        ("approve", approve_command),
        ("reject", reject_command),
    ):
        application.add_handler(CommandHandler(command, handler))

    application.add_handler(
        MessageHandler(filters.Dice.ALL, manual_game_roll_handler)
    )
    application.add_handler(CallbackQueryHandler(callback_router))
    application.add_handler(MessageHandler(filters.COMMAND, unknown_command))
    application.add_error_handler(error_handler)
    return application


def main() -> None:
    if sys.version_info < (3, 9):
        raise RuntimeError("Python 3.9 or newer is required.")
    try:
        import telegram
        version_parts = tuple(
            int(part) for part in re.match(r"^(\d+)\.(\d+)", telegram.__version__).groups()
        )
    except Exception as exc:
        raise RuntimeError("python-telegram-bot 22.7 or newer is required.") from exc
    if version_parts < (22, 7):
        raise RuntimeError(
            f"python-telegram-bot 22.7+ is required for Bot API 9.4 button styles; installed: {telegram.__version__}"
        )
    application = build_application()
    LOGGER.info("Database: %s", DB.path)
    application.run_polling(
        allowed_updates=Update.ALL_TYPES,
        drop_pending_updates=False,
        close_loop=True,
    )


if __name__ == "__main__":
    main()
